'use strict';
(() => {
const D=globalThis.RA.D;
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({wrong,right,reason,errorType});
const Q=(s,prompt,answer,wrong1,wrong2,explain,errorType='meaning')=>({s,prompt,answer,wrong1,wrong2,explain,errorType});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:w==='riproarious'?'Etymonline: https://www.etymonline.com/word/uproarious':w==='rimption'?'Project source labels this as a dialect word; deeper etymology remains uncertain.':`Etymonline: https://www.etymonline.com/word/${w.toLowerCase().replaceAll(' ','-')}`});
const P=(w,origin,contexts,mistake,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(contexts)?contexts:[contexts],mistakes:[mistake],quiz:qs.map((q,i)=>({id:`${w}.q${i+1}`,senseId:`${w}.s${q.s}`,prompt:q.prompt,answer:q.answer,options:[q.answer,q.wrong1,q.wrong2],explain:q.explain,errorType:q.errorType,type:'辨义与用法'}))});
P('riddle','From Old English rædels “riddle,” related to rædan “interpret, advise”; riddle is a puzzling question, a hard-to-understand person or situation, or to fill something with many holes.',[C('riddle.s1','通用','The children solved the riddle by noticing that the answer was hidden in the first letters.','孩子们发现答案藏在每句话的首字母里，解开了这个谜语。','solve/pose a riddle','名词：需要猜出隐含答案的谜语或问题。','answer is concealed.','通用'),C('riddle.s2','书面','The sudden disappearance of the ship remains a riddle to investigators.','这艘船突然失踪，对调查人员来说仍是个谜。','a riddle to + person; a riddle of + situation','名词：难以理解的人或情况。','cause remains unexplained.','书面'),C('riddle.s3','书面','The hailstones riddled the greenhouse roof with small holes.','冰雹在温室屋顶砸出了许多小洞。','riddle something with holes/bullets','动词：使某物布满孔洞。','hail makes holes.','书面')],M('The children solved the riddle immediately because its answer was plainly printed beside the question.','The children solved the riddle by working out its hidden answer.','答案若直接印在题旁就不是需要猜出的谜语。','meaning'),[Q(1,'A child solves a riddle by…','guessing its hidden answer','filling a roof with holes','reprinting the question','Sense 1 is a puzzling question that must be answered.','meaning'),Q(2,'The missing ship is a riddle to investigators because…','they cannot understand what happened','it is an easy question with an obvious answer','the ship is a passenger','Sense 2 describes a puzzling situation.','context'),Q(3,'Hail riddled the roof with holes. What happened?','The hail made many holes in the roof.','The hail solved a puzzle on the roof.','The roof became a riddle for passengers.','Riddle as a verb can mean fill something with holes.','meaning'),Q(1,'Which phrase is natural?','solve a riddle','solve to a riddle','riddle an answer with','Solve is commonly used with a riddle as its object.','collocation')]);
P('ride','From Old English rīdan “ride, travel,” a Germanic verb; ride means sit on an animal or bicycle and travel, or a journey or amusement-park attraction.',[C('ride.s1','通用','We rode our bicycles along the river path before sunset.','日落前，我们沿着河边小路骑自行车。','ride a horse/bike; ride on an animal','动词：骑在动物或自行车上并操控前行，也可乘车出行。','cyclists travel on bikes.','通用'),C('ride.s2','通用','The bus ride from the airport took about forty minutes.','从机场乘公交车的这段路程大约花了四十分钟。','a ride to/from + place; take a ride','名词：乘车、骑行的旅程，也指游乐场设施。','journey lasts forty minutes.','通用')],M('We rode our bicycles by carrying them in the car while we remained on foot.','We rode our bicycles along the river path.','步行并把自行车放在车里，不是骑车出行。','meaning'),[Q(1,'They rode their bicycles along the path. They…','sat on and traveled by bicycle','carried the bicycles while walking','made a reservation for bicycles','Ride sense 1 means travel on a bicycle or animal.','meaning'),Q(2,'A bus ride is…','a journey made by bus','the bus driver’s job only','a road with no vehicles','Ride as a noun can name a journey in a vehicle.','context'),Q(1,'Which sentence uses ride as a verb?','She rides her horse every morning.','The ride lasted an hour.','We enjoyed the fairground ride.','In the first sentence, rides is an action verb.','grammar'),Q(2,'Which phrase is natural?','a ride to the airport','a ride at the airport to of','riding the airport with a journey','To can identify the destination of a ride.','collocation')]);
P('rider','From ride + -er, from Old English rīdan “travel”; rider means someone riding an animal, bicycle, or motorcycle, or a passenger in a vehicle.',[C('rider.s1','交通','Every rider wore a bright helmet on the mountain-bike trail.','山地自行车道上的每位骑行者都戴着醒目的头盔。','a horse/bicycle/motorcycle rider','名词：骑马、骑自行车或骑摩托车的人。','cyclist wears helmet.','交通'),C('rider.s2','交通','The bus driver waited until every rider had found a seat.','公交司机等到每位乘客都找到座位后才开车。','a passenger/rider on + vehicle','名词：乘坐车辆但不负责驾驶的人。','people travel as passengers.','交通')],M('The rider drove the bus while the professional driver sat in the back as a passenger.','The driver operated the bus while the riders traveled as passengers.','rider是乘坐者，不是驾驶公交车的人。','distinction'),[Q(1,'A mountain-bike rider is…','a person riding the bicycle','the bicycle’s passenger who never rides','a person who repairs only roads','Sense 1 names someone who rides a bike.','meaning'),Q(2,'A bus rider is usually…','a passenger traveling on the bus','the person steering the bus','a horse on the bus','Sense 2 means passenger rather than driver.','context'),Q(1,'Which phrase is natural?','a rider on a motorcycle','a rider to a motorcycle the','a riding of motorcycle person','A rider can be identified by the vehicle they ride.','grammar'),Q(1,'Which person is a rider in the cycling sense?','Someone pedaling a bicycle along a trail.','Someone reading a bus timetable from home.','Someone designing a road map.','The rider is the person traveling on the bicycle.','meaning')]);
P('ridge','From Old English hrycg “back, ridge,” of Germanic origin; a ridge is a long narrow high line of land or a raised line where surfaces meet.',[C('ridge.s1','地理','A narrow ridge separated the valley from the steep land beyond it.','一道狭长的山脊把山谷与更远处的陡坡隔开。','a mountain/ridge line; ridge between + places','名词：山丘或山脉上狭长的高地。','high ground runs along hill.','地理'),C('ridge.s2','通用','The metal roof has a raised ridge where its two sloping sides meet.','金属屋顶两侧斜面交接处有一道凸起的屋脊。','a roof ridge; ridge on + surface','名词：表面上隆起的一条脊线。','sloping surfaces meet.','建筑')],M('The hikers stood in the valley floor and called the lowest point between two hills the ridge.','The hikers followed the narrow high ridge above the valley.','山脊是狭长高地，不是两座山之间的最低谷地。','meaning'),[Q(1,'A ridge above a valley is…','a long narrow line of high ground','a low ditch on a flat road','a person riding a horse','Ridge sense 1 is high ground along a hill.','meaning'),Q(2,'The ridge of a roof is where…','its two sloping sides meet in a raised line','the roof meets the basement','rainwater is stored in a reservoir','Sense 2 is a raised seam or line on a surface.','context'),Q(1,'Which phrase is natural?','walk along the mountain ridge','walk under the ridge of a mountain down','ridge the mountain to walking','A ridge can be followed along its length.','grammar'),Q(1,'A raised line of soil in a field can also be called a…','ridge','rider','riddle','The word also applies to a raised line on a surface.','meaning')]);
P('ridicule','From Latin ridiculus “laughable,” from ridere “laugh”; ridicule means laugh at someone unkindly or words and laughter intended to make someone seem foolish.',[C('ridicule.s1','通用','The classmates ridiculed his accent instead of listening to his presentation.','同学们没有认真听他的演讲，反而嘲笑他的口音。','ridicule someone/something for + feature','动词：以不友善的方式嘲笑某人或某观点。','peers mock accent.','通用'),C('ridicule.s2','通用','She faced ridicule for proposing a safer design before the accident.','事故发生前，她因提出更安全的设计而遭到嘲笑。','face/be subjected to ridicule','名词：嘲笑或让某人显得愚蠢的话语。','proposal attracts mockery.','通用')],M('The classmates ridiculed his accent by praising it respectfully and refusing to laugh at him.','The classmates ridiculed his accent by imitating it to make him seem foolish.','尊重并赞扬某人的口音与嘲笑相反。','meaning'),[Q(1,'To ridicule a classmate’s accent is to…','mock it in an unkind way','praise it respectfully','ride with the classmate','Ridicule as a verb means laugh at someone unkindly.','meaning'),Q(2,'She faced ridicule for her proposal. She faced…','words or laughter meant to make her seem foolish','a formal ride to the meeting','an official award','Ridicule as a noun means mockery.','context'),Q(1,'Which construction is correct?','ridicule someone for an error','ridicule to someone for an error','ridicule someone at error with','For introduces the feature or action being mocked.','grammar'),Q(1,'Which word is closest to ridicule?','mock','respect','reimburse','Ridicule means mock or make fun of.','meaning')]);
P('ridiculous','From Latin ridiculus “laughable,” from ridere “laugh”; ridiculous describes something so silly or unreasonable that it invites laughter.',C('ridiculous.s1','通用','It would be ridiculous to carry an umbrella indoors on a cloudless day.','晴空万里还在室内撑伞，实在荒唐。','a ridiculous idea/excuse; ridiculous to + verb','形容词：愚蠢、不合情理，令人发笑。','action makes no sense.','通用'),M('The excuse was ridiculous because it was carefully documented, reasonable, and fully supported by evidence.','The excuse was ridiculous because its claims were absurd and unsupported.','有理有据的解释不能仅因无理荒唐而称 ridiculous。','meaning'),[Q(1,'A ridiculous excuse is…','absurd or unreasonable','carefully verified and sensible','a passenger on a bus','Ridiculous describes something silly or unreasonable.','meaning'),Q(1,'Which phrase is natural?','a ridiculous suggestion','a ridiculousness suggestionly','ridiculously suggestion to','Ridiculous is an adjective modifying suggestion.','grammar'),Q(1,'Someone claims the sun rises in the west every day. The claim is…','ridiculous','righteous','rigidly','It is plainly unreasonable.','context'),Q(1,'The historical root of ridiculous is linked with…','laughing','riding','residing','The Latin source ridiculus means laughable.','word-formation')]);
P('ridiculousness','From ridiculous + -ness; ridiculous is from Latin ridiculus “laughable.” Ridiculousness is the quality of being silly or unreasonable.',C('ridiculousness.s1','通用','The ridiculousness of the rule became clear when nobody could explain its purpose.','没人能解释这条规定的目的，其荒谬之处便显而易见。','the ridiculousness of + idea/rule','名词：某事愚蠢、不合情理的性质。','rule has no rationale.','通用'),M('The ridiculousness of the plan was obvious because every step was practical, sensible, and well supported.','The ridiculousness of the plan was obvious because its steps were impossible and illogical.','实际可行且有充分依据的计划并不荒谬。','meaning'),[Q(1,'The ridiculousness of a rule is…','its silly or unreasonable quality','its legal right to exist','its ability to resist heat','Ridiculousness names the quality of being ridiculous.','meaning'),Q(1,'Which phrase is natural?','the ridiculousness of the proposal','the ridiculous of proposalness','ridiculousness to proposing at','The noun is commonly followed by of.','grammar'),Q(1,'A plan requires a person to walk through a locked wall. Its…','ridiculousness is obvious','resilience is measurable','residence is required','The plan is unreasonable, so it is ridiculous.','context'),Q(1,'Which suffix forms ridiculousness?','-ness','-er','-able','The suffix -ness forms a noun naming a quality.','word-formation')]);
P('rifle','From French rifle, perhaps related to rifler “scratch, groove”; rifle is a shoulder-fired long gun, or to search quickly through belongings, often to steal.',[C('rifle.s1','军事','The museum displayed a historic rifle behind thick protective glass.','博物馆把一支历史悠久的步枪陈列在厚厚的防护玻璃后。','a hunting/service rifle; fire a rifle','名词：抵肩瞄准射击的长枪。','museum exhibits firearm.','军事'),C('rifle.s2','通用','The thief rifled through the desk drawers but left the locked cabinet untouched.','小偷迅速翻遍了书桌抽屉，却没有动上锁的柜子。','rifle through + drawer/bag','动词：快速翻找物品，常带有偷窃意图。','drawers searched hurriedly.','通用')],M('The visitor picked up a rifle and was allowed to handle it freely in the museum gallery.','The visitor viewed the rifle safely behind protective glass in the museum gallery.','博物馆中被隔离展示的枪支不应被访客随意拿取。','meaning'),[Q(1,'A rifle is…','a long gun held against the shoulder','a small curl of hair','a bus passenger','Sense 1 names a type of firearm.','meaning'),Q(2,'The thief rifled through the desk. The thief…','searched its contents quickly','polished the desk carefully','reserved the desk for later','Rifle through means search hurriedly.','context'),Q(1,'Which phrase is natural?','rifle through a bag','rifle a bag throughly','rifle to the bag from','Through introduces the belongings being searched.','grammar'),Q(1,'Which sentence uses rifle as a noun?','The guard stored the rifle securely.','The thief rifled through the drawer.','They rode past the museum.','In the first sentence, rifle names a gun.','meaning')]);
P('rift','From Old Norse rift “cleft, crack,” related to rive “split”; rift is a narrow crack in rock, a serious break in relations, or to split something open.',[C('rift.s1','地质','A deep rift in the rock exposed a layer of dark volcanic stone.','岩石中的一道深裂缝露出了下面一层深色火山岩。','a rift in + rock/ground','名词：岩石或地面中的狭长裂缝。','crack reveals layer.','地质'),C('rift.s2','通用','A rift developed between the partners after they disagreed over the company’s future.','两位合伙人对公司的未来意见不合，彼此间出现了裂痕。','a rift between + people/groups','名词：人或群体间严重的关系破裂。','disagreement divides partners.','通用'),C('rift.s3','通用','The earthquake rifted the dry plain and split the road in two.','地震使干燥的平原裂开，把公路断成两截。','rift something open; rift between + groups','动词：使地面裂开或造成关系分裂。','quake splits plain.','地质')],M('The partners’ rift disappeared because they agreed completely and strengthened their friendly relationship.','The partners’ rift widened because they continued to disagree over the company’s future.','一致同意且关系加强与两人产生裂痕相反。','meaning'),[Q(1,'A rift in rock is…','a long narrow crack','a raised hilltop ridge','a circle of people','Sense 1 is a geological fissure.','meaning'),Q(2,'A rift between business partners is…','a serious break in their relationship','a shared company reservation','a successful rescue','Sense 2 is a relationship division.','context'),Q(3,'An earthquake rifted the plain means it…','split the ground open','made the plain a republic','reprinted the road map','Rift as a verb means split or open a fissure.','meaning'),Q(1,'Which phrase is natural?','a rift between the two groups','a rift among the two groups between','rift the groups by a friendship','Between introduces the sides of a dispute.','grammar')]);
P('rig','From Old Norse rigga “equip a ship,” of uncertain deeper origin; rig means dishonestly arrange a result, fit a ship or structure with equipment, or a large oil-drilling structure or set of gear.',[C('rig.s1','政治','Investigators found that the candidates had rigged the local vote count.','调查人员发现，候选人操纵了当地的选票统计。','rig an election/contest/result','动词：以不正当方式操纵比赛或选举结果。','vote count manipulated.','政治'),C('rig.s2','航海','The crew rigged the small boat with ropes before setting sail.','启航前，船员用绳索给小船装配好了设备。','rig a ship/sail/structure with + equipment','动词：用绳索和装备装配船只或结构。','crew outfits vessel.','航海'),C('rig.s3','工业','A drilling rig stood offshore beside the platform’s supply vessel.','一座钻井平台矗立在海上，旁边停着平台的补给船。','an oil/drilling rig; a truck rig','名词：大型钻探设施，也可指船或车辆所配备的一套器材。','offshore structure drills.','工业')],M('The committee rigged the contest fairly by following the published rules and counting every vote independently.','The committee rigged the contest by secretly changing votes to ensure a chosen candidate won.','遵守规则、独立计票是公平比赛，不是操纵。','meaning'),[Q(1,'To rig an election is to…','dishonestly manipulate its result','hold a fair vote under the rules','move a plant to a new pot','Sense 1 is fraudulent arrangement.','meaning'),Q(2,'The crew rigged the boat before sailing. They…','fitted it with ropes and equipment','stole its voting records','tore a crack in the hull','Sense 2 means outfit or equip a vessel.','context'),Q(3,'An offshore drilling rig is…','a large structure used for oil drilling','a passenger traveling by bus','a curled lock of hair','Sense 3 is industrial equipment or structure.','meaning'),Q(1,'Which phrase is natural?','rig the election','rig to the election unfairly of','rigging the election with no change','Rig as a verb takes the contest or result as its object.','grammar')]);
P('right','From Old English riht “straight, just,” from a Germanic root; right can mean correct, on the side opposite left, a moral or legal claim, exactly or immediately, or to correct something.',[C('right.s1','通用','Your answer is right: the bridge opened in 1924.','你的答案正确：这座桥于1924年开放。','the right answer; be right about + fact','形容词：正确、真实或合适的。','answer matches fact.','通用'),C('right.s2','通用','Turn right at the next intersection and continue for two blocks.','在下一个路口向右转，再走两个街区。','turn/go right; on the right','副词/形容词：左侧的相反方向或朝该方向。','direction is opposite left.','通用'),C('right.s3','法律','Every tenant has the right to request repairs to unsafe wiring.','每位租户都有权要求修理不安全的线路。','the right to + verb; have a right to + noun','名词：法律或道德上可享有或做某事的权利。','tenant holds legal claim.','法律'),C('right.s4','口语','The technician arrived right after the alarm sounded.','警报响起后，技术员马上就到了。','right after/beside/away; right + adjective','副词：恰好、立刻或顺利地。','arrival is immediate.','口语'),C('right.s5','书面','Could you right the fallen sign before the parade begins?','游行开始前，你能把倒下的标牌扶正吗？','right a wrong/boat/sign','动词：把某物恢复到正确位置或状态。','sign is returned upright.','书面')],M('At the intersection, turn right toward the left-hand side of the road.','At the intersection, turn right toward the side opposite the left-hand side.','right与left方向相反，不能同时朝向左侧。','distinction'),[Q(1,'An answer that is right is…','correct','on the left side','a legal claim','Sense 1 means true or correct.','meaning'),Q(2,'Turn right at the junction means…','go toward the side opposite left','continue straight without turning','claim a legal entitlement','Sense 2 concerns direction.','context'),Q(3,'A tenant’s right to request repairs is…','a legal or moral entitlement','the tenant’s correct answer','a request that repairs be delayed','Sense 3 is an entitlement.','meaning'),Q(4,'“The technician arrived right after the alarm” means…','immediately after it','on the left side of it','to correct the alarm','Right can mean immediately in this phrase.','context')]);
P('righteous','From right + -eous, ultimately from Old English riht “just”; righteous means morally fair and good, or feeling anger because something seems unjust.',[C('righteous.s1','通用','The judge was praised for making a righteous decision despite pressure from powerful donors.','尽管受到权势捐赠者施压，法官仍作出公正的裁决，受到赞扬。','a righteous decision/cause/person','形容词：行为公正、符合道德的。','decision follows fairness.','通用'),C('righteous.s2','通用','Residents voiced righteous anger after the unsafe bridge was ignored for years.','这座不安全的桥多年无人处理后，居民表达了义愤。','righteous anger/indignation','形容词：因某事显得不公而感到或表现出愤怒。','anger responds to injustice.','通用')],M('The official called the corrupt decision righteous even though it knowingly denied fair treatment to the public.','The official called the fair decision righteous because it protected equal treatment.','腐败且剥夺公平待遇的决定不具正义性。','meaning'),[Q(1,'A righteous decision is…','morally fair and right','dishonest and biased','a road with a ridge','Sense 1 concerns moral justice.','meaning'),Q(2,'Righteous anger is anger…','felt because something seems unjust','caused by a delicious meal','without any cause or concern','Sense 2 is anger at unfairness.','context'),Q(1,'Which phrase is natural?','a righteous cause','a righteousness causeful','a righting cause in righteous','Righteous can modify cause.','grammar'),Q(1,'Which word is closest to righteous in the moral sense?','just','unfair','ridiculous','Righteous means morally right or fair.','meaning')]);
P('rigid','From Latin rigidus “stiff,” from rigere “be stiff”; rigid means physically stiff and hard to bend, or unwilling to change rules, ideas, or behavior.',[C('rigid.s1','物理','The rigid plastic panel kept its shape when the wind struck it.','坚硬的塑料板在风吹来时保持了原有形状。','rigid material/frame/structure','形容词：僵硬、不易弯曲的。','panel resists bending.','物理'),C('rigid.s2','通用','The school replaced its rigid attendance rule with a policy for emergencies.','学校用一项应急政策取代了僵化的出勤规定。','rigid rules/attitude/schedule','形容词：不愿改变规则、意见或做法的；死板的。','policy had no flexibility.','通用')],M('The rigid metal bar bent easily under a light touch.','The rigid metal bar kept its shape under pressure.','轻触就容易弯曲说明金属条并不坚硬僵直。','meaning'),[Q(1,'A rigid panel is…','stiff and difficult to bend','soft and easily folded','a rider on a bicycle','Sense 1 describes physical stiffness.','meaning'),Q(2,'A rigid attendance rule…','allows no flexibility or exceptions','changes freely for every case','is a legal right','Sense 2 describes an inflexible rule.','context'),Q(1,'Which phrase is natural?','a rigid frame','a rigidity frame','rigidly frame of','Rigid is an adjective modifying frame.','grammar'),Q(1,'Which word is closest to rigid in a policy context?','inflexible','adaptable','righteous','Rigid rules are not readily changed.','meaning')]);
P('rigidity','From rigid + -ity, from Latin rigidus “stiff”; rigidity is physical stiffness that makes movement difficult or the refusal of rules and ideas to change.',[C('rigidity.s1','通用','The patient’s joint rigidity made it difficult to bend the knee.','患者的关节僵硬使膝盖难以弯曲。','muscle/joint rigidity','名词：身体僵硬、活动困难的状态。','joint resists movement.','医学'),C('rigidity.s2','通用','The rigidity of the approval process delayed every small repair.','审批流程的僵化拖延了每一项小型维修。','rigidity of rules/system/method','名词：制度、规则或观念不肯改变的僵化。','process permits no adjustment.','通用')],M('The rigidity of the process made quick changes easy and allowed staff to adjust every step freely.','The rigidity of the process made quick changes difficult because every step required the same approval.','能自由调整并快速改动表明流程灵活而非僵化。','meaning'),[Q(1,'Joint rigidity is…','stiffness that makes movement difficult','a legal right to medical care','a mountain ridge','Sense 1 is bodily stiffness.','meaning'),Q(2,'Rigidity in an approval system means…','it refuses to adapt or change','it adjusts easily to each case','it produces a high-quality image','Sense 2 concerns inflexible rules or methods.','context'),Q(1,'Which phrase is natural?','rigidity of the rules','rigidly of rulesness','the rules rigidityly','Rigidity is a noun often followed by of.','grammar'),Q(1,'Which adjective is the base of rigidity?','rigid','rigorous','righteous','Rigidity is formed from rigid with -ity.','word-formation')]);
P('rigidly','From rigid + -ly, from Latin rigidus “stiff”; rigidly means in a stiff manner or so strictly that exceptions and changes are not allowed.',C('rigidly.s1','通用','The instructor rigidly followed the checklist and would not skip any required safety step.','教员严格按清单执行，不肯跳过任何必要的安全步骤。','rigidly enforce/follow/define','副词：僵硬地，或严格到不允许变通地。','checklist enforced without exceptions.','通用'),M('The manager applied the rule rigidly by changing it whenever each person asked for an exception.','The manager applied the rule rigidly and allowed no exceptions.','频繁变通、应请求例外不是严格僵化地执行。','meaning'),[Q(1,'To follow a checklist rigidly is to…','follow it strictly without exceptions','change it freely each time','ride along the checklist','Rigidly means in a strict or inflexible way.','meaning'),Q(1,'Which sentence uses rigidly correctly?','The rule was rigidly enforced.','The rule was a rigidly policy.','Rigidly, the policy enforce tomorrow.','Rigidly is an adverb modifying enforced.','grammar'),Q(1,'A manager refuses every exception to a fixed policy. The manager applies it…','rigidly','rightly to the left','righteously only','No changes or exceptions are allowed.','context'),Q(1,'Rigidly is formed from the adjective…','rigid','rigidity','ridge','The suffix -ly forms an adverb from rigid.','word-formation')]);
P('rigor','From Latin rigor “stiffness, severity,” from rigere “be stiff”; rigor is severity or strictness, or exactness and thoroughness in thinking and research.',[C('rigor.s1','书面','The hikers endured the rigor of winter travel in the high mountains.','徒步者们经受住了高山冬季行程的严酷考验。','the rigor of + conditions/training','名词：环境、训练或纪律的严酷与严格。','winter conditions are severe.','书面'),C('rigor.s2','学术','The journal praised the study’s rigor because its methods and calculations were checked carefully.','期刊赞扬这项研究严谨，因为研究方法和计算都经过仔细核查。','academic/scientific rigor','名词：推理、方法精确、逻辑严密且全面的品质。','methods withstand scrutiny.','学术')],M('The study lacked rigor because the researchers carefully checked every method and calculation.','The study showed rigor because the researchers carefully checked every method and calculation.','细致核查体现严谨，不是缺乏严谨。','meaning'),[Q(1,'The rigor of winter travel refers to…','its harshness and severity','the number of people on a ride','the accuracy of an image only','Sense 1 concerns severe conditions.','meaning'),Q(2,'Scientific rigor means methods are…','careful, exact, and thorough','chosen without checking','rigid and impossible to bend','Sense 2 is precision and thoroughness in research.','context'),Q(1,'Which phrase is natural?','the rigor of the analysis','the rigorous of analysisly','rigor at the analysis for','Rigor can be followed by of to identify what is strict or exact.','grammar'),Q(1,'Which word is closest to rigor in research?','thoroughness','carelessness','resemblance','Research rigor concerns careful, exact methods.','meaning')]);
P('rigorous','From rigor + -ous, from Latin rigor “strictness”; rigorous means very thorough and careful, applying exact standards.',C('rigorous.s1','科学','The laboratory used a rigorous protocol to prevent contamination during each test.','实验室采用了严格严谨的规程，防止每次测试受到污染。','rigorous test/method/review','形容词：彻底、仔细并符合精确标准的。','protocol guards each step.','科学'),M('The report was rigorous because its authors skipped the data checks and ignored contradictory results.','The report was rigorous because its authors checked the data and addressed contradictory results.','跳过核查、无视相反结果不符合严谨标准。','meaning'),[Q(1,'A rigorous laboratory method is…','careful and exact','careless and unchecked','a method for riding a horse','Rigorous means thorough and exact.','meaning'),Q(1,'Which phrase is natural?','a rigorous review of the evidence','a rigorously review the evidence','a rigorous of evidence reviewing','Rigorous is an adjective modifying review.','grammar'),Q(1,'Researchers repeat tests and examine conflicting data. Their study is…','rigorous','ridiculous','rime','They apply careful, exact standards.','context'),Q(1,'Rigorous is formed from the noun…','rigor','right','rider','The adjective adds -ous to rigor.','word-formation')]);
P('rigorously','From rigorous + -ly, from Latin rigor “strictness”; rigorously means with thoroughness and exact standards, or with severity.',C('rigorously.s1','学术','The team rigorously tested each sample twice before publishing the results.','团队在公布结果前对每个样本都进行了两次严格测试。','rigorously test/check/enforce','副词：以彻底细致、符合精确标准的方式。','repeated checks verify samples.','学术'),M('The team rigorously checked the samples by skipping all tests and publishing guesses.','The team rigorously checked the samples by repeating the tests and reviewing the measurements.','跳过测试、凭猜测发布不符合严格核验。','meaning'),[Q(1,'The samples were rigorously tested. They were tested…','thoroughly and carefully','without any checks','while riding a bicycle','Rigorously means with exactness and thoroughness.','meaning'),Q(1,'Which sentence is correct?','The policy was rigorously enforced.','The policy was a rigorous enforcedly.','They rigorous enforced the policy.','Rigorously is the adverb modifying enforced.','grammar'),Q(1,'A scientist verifies every measurement twice. She works…','rigorously','ridiculously','righteously at once','Her approach is exact and thorough.','context'),Q(1,'Rigorously is the adverb form of…','rigorous','rigor','rigidity','-ly forms an adverb from rigorous.','word-formation')]);
P('rim','From Old English rima “edge, border,” of Germanic origin; a rim is the outer edge of a round object or the outer ring of a wheel.',[C('rim.s1','通用','A thin line of foam formed around the rim of the coffee cup.','咖啡杯口边缘形成了一圈薄薄的泡沫。','rim of a cup/container; along the rim','名词：杯子或其他圆形物体的外沿。','foam marks cup edge.','生活'),C('rim.s2','交通','The mechanic replaced the bent metal rim on the bicycle wheel.','技师更换了自行车轮上弯曲的金属轮辋。','wheel rim; rim of a tire','名词：车轮外圈或轮辋。','wheel ring damaged.','交通')],M('Foam collected in the center of the cup, and the barista called that center the cup’s rim.','Foam collected around the outer edge, or rim, of the cup.','rim指外缘，不是杯子中心。','meaning'),[Q(1,'The rim of a cup is…','its outer edge','the liquid at the center','the handle only','Sense 1 is the outside edge of a round object.','meaning'),Q(2,'A wheel rim is…','the outer ring of the wheel','the center axle only','the cyclist riding it','Sense 2 refers to the wheel’s outer ring.','context'),Q(1,'Which phrase is natural?','the rim of the glass','the glass rimmed at center','rim to the glass of up','Of identifies the round object whose edge is meant.','grammar'),Q(1,'Where would foam form if it gathered around a cup’s rim?','around the cup’s outer edge','in the middle only','under the table','The rim is the circular outer border.','context')]);
P('rime','From Old English hrīm “hoarfrost,” of Germanic origin; rime is a white deposit of ice crystals, especially frost formed from freezing fog on cold surfaces.',C('rime.s1','气象','By dawn, rime coated the fence where supercooled fog had frozen on the cold wire.','天亮时，过冷雾气在冰冷的铁丝上冻结，形成一层雾凇。','rime on + cold surface; a coating of rime','名词：过冷雾滴接触冷表面后冻结形成的白色冰晶层。','fog freezes on wire.','气象'),M('The forecast called the dry, warm afternoon air and sunlit fence a coating of rime.','The forecast called the ice crystals formed from freezing fog on the cold fence rime.','温暖干燥、没有结冰的表面不会形成雾凇。','meaning'),[Q(1,'Rime on a fence is…','ice crystals deposited from freezing fog','a ring around a cup','a ride in a vehicle','Rime is a white frost-like ice deposit.','meaning'),Q(1,'Which phrase is natural?','rime on the cold branches','rime under the warm sunlight only','rime a branch with no ice','Rime forms on cold surfaces.','grammar'),Q(1,'A white icy coating forms as fog droplets freeze on a wire. It is…','rime','rider','rigor','That process produces rime.','context'),Q(1,'Which weather condition is especially associated with rime?','freezing fog on cold surfaces','hot dry air indoors','a clear summer road','Rime forms when supercooled fog freezes onto objects.','meaning')]);
P('rimption','A regional English dialect noun attested for a large amount or great number; its deeper derivation is uncertain, so no root or suffix is assigned.',C('rimption.s1','方言','We found a rimption of wild berries along the old footpath.','我们在旧小径旁发现了一大堆野生浆果。','a rimption of + plural noun','方言名词：大量、许多；该词的具体历史词源不确定。','large quantity of berries.','方言'),M('They had only one berry, yet described it as a rimption of fruit.','They had a rimption of berries, enough to fill several baskets.','rimption means a large amount, not one item.','meaning'),[Q(1,'In regional informal use, a rimption of berries means…','a great quantity of berries','one berry only','a ring-shaped berry','Rimption is a dialect word for a large amount.','meaning'),Q(1,'Which phrase fits the source sense?','a rimption of apples','a rimption of a single apple only','rimption the apples into a circle','The noun is used for an abundant quantity.','collocation'),Q(1,'A speaker says there was a rimption of snow after the storm. There was…','a great deal of snow','no snow at all','a formal ceremony','The regional sense means a large quantity.','context'),Q(1,'What is the safest etymological claim about rimption here?','Its deeper derivation is uncertain.','It certainly comes from Latin rima.','It is formed from ring plus -tion.','The available source marks it as dialectal but does not establish its deeper origin.','word-formation')]);
P('rind','From Old English rinde “bark, crust,” of Germanic origin; rind is the hard outer skin of fruit or the outer layer of cheese.',C('rind.s1','饮食','Remove the thick rind from the melon before cutting the flesh into cubes.','把瓜瓤切成方块之前，先去掉厚厚的外皮。','rind of a fruit/cheese; remove/peel the rind','名词：水果坚硬的外皮或奶酪外层。','outer skin removed.','饮食'),M('The recipe told her to remove the melon’s rind by leaving the entire hard outer skin on the plate.','The recipe told her to remove the melon’s rind before slicing the fruit.','rind就是要去除的外皮，不是留在盘里的果肉。','meaning'),[Q(1,'The rind of a melon is…','its hard outer skin','the soft center only','the seeds after planting','Rind names a fruit’s tough outside layer.','meaning'),Q(1,'Which food also has a rind?','cheese','tea','boiled rice','Some cheeses have an outer rind.','context'),Q(1,'Which phrase is natural?','peel the rind from the fruit','rind the fruit with its inside','peel the fruit of its rindly','Rind can be removed or peeled from fruit.','grammar'),Q(1,'A cook cuts away the outside layer of a citrus fruit. The cook removes its…','rind','rim','ringlet','The outer skin of fruit is called rind.','meaning')]);
P('ring','From Old English hring “circle, ring,” of Germanic origin; ring can name circular jewelry or a group, bell or phone sound and a call, a musical sound, or the act of surrounding.',[C('ring.s1','通用','He gave her a silver ring in a small velvet box.','他把一枚银戒指装在小天鹅绒盒子里送给她。','a ring on/in + finger/box; a ring of people','名词：戴在手指上的戒指，或任何环状物/群体。','circular jewelry.','通用'),C('ring.s2','通讯','I heard the phone ring, so I called the office back.','我听见电话铃响了，于是给办公室回了电话。','the phone/bell rings; ring someone','名词：电话或钟发出的声音；动词：给某人打电话。','phone sound prompts callback.','通讯'),C('ring.s3','通用','The glass rang clearly when she tapped its rim with a spoon.','她用勺子敲了敲杯沿，玻璃杯发出清脆的声音。','ring clearly/out; ears ring','动词：发出清亮的乐音，也可指耳中嗡鸣。','glass makes clear sound.','通用'),C('ring.s4','书面','Police ringed the building while the negotiator spoke with the occupants.','谈判代表与楼内人员交谈时，警察包围了大楼。','ring a place/person with + guards','动词：围住某人或某地。','officers surround building.','书面')],M('The police ringed the building by leaving every entrance open and standing far away.','The police ringed the building by surrounding it with officers.','留出所有入口且不包围建筑，与ring的“围住”义相反。','meaning'),[Q(1,'A ring in a jewelry box is…','a circular piece of jewelry','a call from the phone','a group of police around a building','Sense 1 includes jewelry for a finger.','meaning'),Q(2,'“The phone rang” means…','the phone made its alert sound','someone surrounded the phone','the phone became a ringlet','Sense 2 is a telephone sound.','context'),Q(3,'A glass rings when tapped if it…','makes a clear musical sound','is surrounded by a crowd','is a legal entitlement','Sense 3 is to produce a clear ringing sound.','meaning'),Q(4,'Police ringed the building. They…','surrounded it','telephoned it','gave it jewelry','Ring as a verb can mean surround.','context')]);
P('ringlet','From ring + diminutive -let; ring comes from Old English hring “circle.” A ringlet is a small, often long hanging curl of hair.',C('ringlet.s1','外貌','A single ringlet fell over the child’s forehead in the family photograph.','家庭合照里，一绺卷发垂在孩子的额前。','a ringlet of hair; long ringlets','名词：一小绺卷曲的头发，尤指长而垂下的卷发。','small curl hangs down.','外貌'),M('The stylist called the child’s perfectly straight lock a ringlet.','The stylist called the child’s tight curl a ringlet.','笔直的头发不是卷发。','distinction'),[Q(1,'A ringlet is…','a small curl of hair','a ring-shaped earring only','a long straight road','Ringlet names a little curl.','meaning'),Q(1,'Which phrase is natural?','a ringlet of dark hair','a ringlet of straight metal wire only','a ringlet hairing','Ringlet is often followed by of hair.','grammar'),Q(1,'A long curl hangs beside the dancer’s cheek. It is a…','ringlet','rind','rime','A hanging curl is a ringlet.','context'),Q(1,'The suffix -let in ringlet often suggests…','a small form','a person who rides','a past action','Ringlet is a small ring-like curl.','word-formation')]);
P('rinse','From Old French rincer, perhaps from Latin recens “fresh”; rinse means wash quickly with clean water only, or a quick clean-water wash.',[C('rinse.s1','家居','Rinse the rice in a sieve until the water runs clear.','把米放在筛子里冲洗，直到流出的水变清。','rinse something with/under water; rinse out','动词：只用清水快速冲洗，不用肥皂。','water removes surface starch.','家居'),C('rinse.s2','家居','Give the cups a quick rinse before stacking them in the cupboard.','把杯子快速冲洗一下，再摞进橱柜。','a quick/final rinse; give something a rinse','名词：用清水快速冲洗一遍。','brief wash with water.','家居')],M('She rinsed the cup by coating it with soap and leaving all the soap on without using water.','She rinsed the cup quickly under clean water to remove the soap.','不使用清水冲走污物和肥皂，不算rinse。','meaning'),[Q(1,'To rinse rice is to…','wash it quickly with clean water','scrub it with dry sand only','boil it until it is cooked','Rinse uses clean water for a quick wash.','meaning'),Q(2,'A quick rinse is…','a brief wash with clean water','a long dry heating process','a full day of soaking','Sense 2 is the washing action itself.','context'),Q(1,'Which phrase is natural?','rinse the cup under the tap','rinse the cup with no water','rinse to the cup underly','Under the tap describes how the cup is rinsed.','grammar'),Q(1,'Which sentence uses rinse as a noun?','Give the vegetables a rinse.','Rinse the vegetables now.','The vegetables are rinsed.','In the first sentence, a rinse names the quick wash.','meaning')]);
P('riot','From Middle French riote “dispute, quarrel,” of uncertain deeper origin; riot is a violent crowd disturbance, to take part in one, or a strikingly lively display of something.',[C('riot.s1','社会','The riot began after a small group started smashing windows in the city center.','市中心一小群人开始砸窗后，骚乱爆发了。','a riot breaks out; a violent riot','名词：人群发动袭击或破坏财物的喧闹暴力事件。','crowd violence.','社会'),C('riot.s2','社会','Several people were arrested after they rioted outside the stadium.','几人在体育场外参与骚乱后被捕。','riot in/at + place','动词：作为人群的一员以暴力、喧闹方式行动。','people join violent crowd.','社会'),C('riot.s3','书面','The garden was a riot of color when the spring flowers opened.','春花盛开时，花园里色彩缤纷、热闹非凡。','a riot of + color/activity','名词：某种事物显著而丰富、活跃的场面。','many bright flowers.','书面')],M('The police called the peaceful gathering a riot even though nobody attacked anyone or damaged property.','The police called the violent crowd attack a riot after windows were smashed.','没有暴力、袭击或破坏的和平集会不符合来源中的riot义。','distinction'),[Q(1,'A riot is…','a violent disturbance by a crowd','a peaceful ceremony with no conflict','a ringlet of flowers','Sense 1 is a violent crowd event.','meaning'),Q(2,'The crowd rioted outside the stadium. It…','behaved violently and noisily as a group','quietly waited in separate homes','held a formal rite','Riot as a verb means take part in a violent disturbance.','context'),Q(3,'A garden described as a riot of color has…','a strikingly abundant display of colors','no flowers or color','an organized election','The figurative sense means a vivid, lively abundance.','meaning'),Q(1,'Which phrase is natural?','a riot broke out after the match','the riot of silence had no crowd or noise','riot a flower into the ground','A riot can break out as an event begins.','collocation')]);
P('rip','From Old English rīpan “tear, pull apart,” of Germanic origin; rip means tear something quickly and forcefully, a long tear, or overcharge/cheat in the phrase rip off.',[C('rip.s1','通用','She ripped the envelope open along its sealed edge.','她沿着封口把信封撕开了。','rip something open/off; rip through + material','动词：快速而用力地撕开某物。','envelope torn forcefully.','通用'),C('rip.s2','通用','A long rip in the tent let rain blow through the fabric.','帐篷上的一道长裂口让雨水从布料中吹了进来。','a rip in + cloth/paper','名词：布或纸上的长条裂口。','fabric tear leaks.','通用'),C('rip.s3','口语','The tourist felt ripped off when the shop charged twice the posted price.','店铺收费是标价的两倍，游客觉得自己被宰了。','rip someone off; get ripped off','口语动词：欺诈性地多收费或偷窃。','customer is overcharged.','口语')],M('The tourist was ripped off because the shop charged exactly the posted price and made no extra charge.','The tourist was ripped off because the shop charged twice the posted price.','按标价收费且没有多收费，不是敲竹杠。','meaning'),[Q(1,'She ripped the envelope open. She…','tore it quickly and forcefully','washed it with clean water','gave it a ride','Sense 1 is forceful tearing.','meaning'),Q(2,'A rip in a tent is…','a long tear in the fabric','a smooth unbroken panel','the tent’s reservation','Sense 2 names a tear or hole.','context'),Q(3,'A tourist was ripped off when…','the shop cheated or overcharged them','the shop charged the exact fair price','they tore their own ticket','Rip off means cheat or charge too much.','meaning'),Q(1,'Which phrase is grammatical?','rip the paper in half','rip to the paper in halfing','rip off the paper in a tear','Rip takes the material being torn as a direct object.','grammar')]);
P('ripe','From Old English rīpe “ready for reaping,” from a Germanic root related to reaping; ripe means fruit is ready to eat or conditions are suitable for an event.',[C('ripe.s1','农业','The peaches are ripe now, so we can pick them for the market.','桃子现在熟了，可以采下来送去市场。','ripe fruit; ripe for picking','形容词：果实已充分长成、可以食用。','fruit ready to eat.','农业'),C('ripe.s2','书面','After weeks of discussion, the project is ripe for a final decision.','经过数周讨论，这个项目已经到了作出最终决定的时候。','ripe for + action/change','形容词：条件成熟、适合某事发生。','conditions are ready.','书面')],M('The ripe peaches were hard, green, and unsuitable to eat.','The ripe peaches were soft, sweet, and ready to eat.','硬且未成熟的水果不符合ripe的果实义。','meaning'),[Q(1,'Ripe peaches are…','fully grown and ready to eat','still too green to pick','a source of rime','Sense 1 describes edible mature fruit.','meaning'),Q(2,'A project ripe for a decision is…','ready for a decision to be made','too early for any discussion','a round metal object','Sense 2 describes a suitable time or condition.','context'),Q(1,'Which phrase is natural?','ripe for change','ripe to a change for','ripeness change into ripe','Ripe for introduces a suitable action or development.','grammar'),Q(1,'A soft, sweet fruit ready to pick is…','ripe','risky','rigid','It has matured and is ready to eat.','context')]);
P('ripen','From ripe + -en, with the adjective from Old English rīpe “ready for reaping”; ripen means become ready to eat, or make fruit or crops ready.',[C('ripen.s1','农业','The tomatoes ripen slowly on the vine during the warm weeks of August.','八月温暖的几周里，西红柿在藤上慢慢成熟。','fruit ripens; ripen on the vine','不及物动词：果实逐渐成熟、达到可食状态。','tomatoes mature naturally.','农业'),C('ripen.s2','农业','A few days in a paper bag can ripen green pears more quickly.','把青梨放在纸袋里几天，可以让它们更快成熟。','ripen fruit/crops; ripen something','及物动词：使水果或农作物成熟。','bag helps fruit mature.','农业')],M('The green pears ripened by remaining hard, sour, and unsuitable to eat.','The green pears ripened as they softened and became sweet enough to eat.','未成熟的硬酸状态没有变成可食状态，不能说已成熟。','meaning'),[Q(1,'The tomatoes ripen on the vine means they…','become ready to eat','are picked while still seeds','are washed with clean water','Sense 1 is to become mature.','meaning'),Q(2,'A paper bag can ripen pears by…','helping them become ready to eat','making them permanently unripe','ripping them into pieces','Sense 2 is to make fruit mature.','context'),Q(1,'Which sentence uses ripen as a transitive verb?','Warmth ripened the fruit.','The fruit ripened overnight.','The fruit is ripe.','The first sentence has an agent causing the fruit to mature.','grammar'),Q(1,'Which adjective is the base of ripen?','ripe','rind','ripple','Ripen is formed from ripe with -en.','word-formation')]);
P('ripple','From Middle English ripel, probably imitative of water movement; ripple is a tiny water wave or a small event whose effects spread, and to ripple is move or make small waves.',[C('ripple.s1','通用','A light breeze sent a ripple across the surface of the pond.','微风吹过池面，荡起一道涟漪。','a ripple across/on + water','名词：水面上很小的波纹。','breeze makes wavelet.','通用'),C('ripple.s2','通用','The factory closure caused a ripple of job losses across nearby towns.','工厂关闭在附近城镇引发了一连串失业影响。','a ripple of + effect/change','名词：逐渐扩散开来的小事件或影响。','closure affects other towns.','通用'),C('ripple.s3','通用','The wheat field rippled in the wind as the clouds passed overhead.','云朵掠过时，麦田在风中起伏荡漾。','water/cloth/field ripples; ripple through + place','动词：表面出现小波浪或使其起伏。','plants move in waves.','通用')],M('A breeze made a ripple across the pond, but the water remained perfectly still with no waves.','A breeze made a ripple across the pond, sending a small wave over the surface.','完全静止、没有波纹与形成涟漪矛盾。','meaning'),[Q(1,'A ripple on a pond is…','a very small wave','a deep rift in rock','a ring around a wheel','Sense 1 is a tiny water wave.','meaning'),Q(2,'A ripple of job losses means…','a small effect spreading to other places','one isolated job change with no further effect','a group of riders','Sense 2 is a spreading consequence.','context'),Q(3,'The wheat field rippled in the wind. It…','moved in small waves','became completely rigid','was rinsed with water','Ripple as a verb describes wave-like motion.','meaning'),Q(1,'Which phrase is natural?','a ripple across the surface','ripple to the surface under of','a rippled ripple acrossly','A ripple can move across a surface.','grammar')]);
P('riproarious','A playful American formation from rip + uproarious; rip here intensifies the lively, noisy sense. Riproarious means extremely lively and noisy, especially with laughter.',C('riproarious.s1','口语','The children’s riproarious laughter could be heard from the playground across the street.','孩子们喧闹欢腾的笑声从街对面的操场上传了过来。','riproarious laughter/party/story','形容词：热闹喧腾、笑声不断的，常用于口语。','loud lively laughter.','口语'),M('The quiet library was riproarious, with everyone silent and no laughter or noise.','The birthday party became riproarious as guests laughed and shouted over the music.','寂静无声与喧闹欢腾相反。','meaning'),[Q(1,'A riproarious party is…','extremely lively and noisy','quiet with no guests','a party with a formal rite','Riproarious describes loud high spirits and laughter.','meaning'),Q(1,'Which phrase is natural?','riproarious laughter','riproariously laughtering','a riproarious of laughter','Riproarious can modify laughter.','grammar'),Q(1,'Guests laugh loudly and sing at a lively celebration. The party is…','riproarious','rigid','rime','The celebration is noisy and full of high spirits.','context'),Q(1,'Riproarious is historically associated with…','rip + uproarious','ripe + rigorous','rime + ridiculous','The playful form builds on uproarious with rip as an intensifier.','word-formation')]);
P('rise','From Old English rīsan “rise, get up,” of Germanic origin; rise means move upward or increase in amount, level, or value.',C('rise.s1','通用','The river began to rise after three days of heavy rain.','连续三天下大雨后，河水开始上涨。','rise by/to + amount/level; rise above + place','动词：向上移动，或在数量、水平、价值上增加。','water level increases.','通用'),M('The river rose after the rain, but its level fell lower and lower throughout the storm.','The river rose after the rain as its water level increased.','水位不断下降与上升相反。','meaning'),[Q(1,'The river began to rise after heavy rain. It…','increased in level','dried up immediately','was reprinted','Rise means move upward or increase.','meaning'),Q(1,'Which phrase is correct?','prices rose by five percent','prices rose with five percent by','rose prices of five percent up','Rise can be followed by by to state the amount of increase.','grammar'),Q(1,'A hot-air balloon moves upward into the sky. It…','rises','rinses','rinds','Moving upward is the core meaning.','context'),Q(1,'Which verb is the opposite of rise in level?','fall','resemble','ring','A level that rises goes up; one that falls goes down.','meaning')]);
P('rising','From rise + -ing; rise is from Old English rīsan “move upward.” Rising describes something going up or increasing, or the act of a sun or moon coming up.',[C('rising.s1','商务','The company is worried about rising energy costs this winter.','公司担心今年冬天能源成本不断上升。','rising prices/costs/levels','形容词：正在上涨或增加的。','costs increase.','商务'),C('rising.s2','书面','The rising of the moon lit the path before the hikers returned.','月亮升起，照亮了徒步者返回前的小路。','the rising of the sun/moon','名词：太阳或月亮升起的动作或时刻。','moon comes above horizon.','书面')],M('The company worried about rising costs even though every energy bill was steadily getting lower.','The company worried about rising costs because energy bills were increasing.','费用持续下降不能称为上涨。','meaning'),[Q(1,'Rising energy costs are costs that…','are increasing','have disappeared completely','have been paid back','Sense 1 describes upward change.','meaning'),Q(2,'The rising of the moon is…','the act of coming up above the horizon','a bill for moonlight','the moon’s circular rim','Sense 2 names the moon’s appearance in the sky.','context'),Q(1,'Which phrase is natural?','rising temperatures','risingly temperatures','temperatures risen by the rising','Rising can function as an adjective before a noun.','grammar'),Q(1,'Which sentence uses rising as a noun?','The rising of the sun woke the campers.','The rising sun warmed the tents.','Costs are rising quickly.','In the first sentence, the rising names the event.','meaning')]);
P('risk','From Italian risco, perhaps related to Arabic rizq “what providence supplies,” but the deeper origin is uncertain; risk is the possibility of harm or loss, or to do something despite that possibility.',[C('risk.s1','通用','There is a risk of flooding if the river continues to rise.','如果河水继续上涨，就有发生洪水的风险。','a risk of + harm; at risk','名词：某种坏事发生的可能性。','rising water may flood.','通用'),C('risk.s2','通用','She risked missing the train by stopping to answer a long phone call.','她停下来接一个长电话，冒着赶不上火车的风险。','risk doing something; risk a loss','动词：明知可能出现不良结果仍去做某事。','call may make her late.','通用')],M('There was a risk of flooding even though the river had dried up and no rain was expected.','There was a risk of flooding because the river was rising after heavy rain.','完全干涸且无雨不支持有洪水风险。','meaning'),[Q(1,'A risk of flooding is…','the possibility that flooding may happen','a guarantee that flooding already happened','a type of ring','Risk as a noun is a possibility of something bad.','meaning'),Q(2,'She risked missing the train by taking a phone call. She…','did something that might make her miss it','was certain to catch it early','reserved a seat on the train','Risk as a verb means act despite a possible bad result.','context'),Q(1,'Which construction is correct?','risk losing the ticket','risk to lose the ticket','risk of losing the ticket as a verb','Risk is followed by a gerund when naming an action.','grammar'),Q(1,'Which word is closest to risk as a noun?','danger','certainty','reputation','Risk is the chance of harm or loss.','meaning')]);
P('risky','From risk + -y; risk is the possibility of harm or loss. Risky means involving danger, loss, or the chance of a bad result.',C('risky.s1','通用','Driving across the icy pass at night would be risky without snow tires.','没有雪地胎，夜间开车穿越结冰的山口会很危险。','a risky decision/plan/investment','形容词：可能造成危险、损失或失败的。','conditions raise danger.','通用'),M('It was risky to cross the icy pass at night because the road was perfectly dry and closed to traffic.','It was risky to cross the icy pass at night because the road was icy and visibility was poor.','路面干燥且没有车辆不能解释此行的危险性。','meaning'),[Q(1,'A risky drive is one that…','involves a chance of danger or a bad result','is guaranteed to be safe','takes place on a ring','Risky means involving possible danger or failure.','meaning'),Q(1,'Which phrase is natural?','a risky investment','a riskfully investment','an investment riskyly of','Risky is an adjective modifying investment.','grammar'),Q(1,'Walking across thin ice may be…','risky','righteous','rime','The ice may break, creating danger.','context'),Q(1,'Risky is formed from risk plus…','-y','-ness','-ment','The suffix -y forms the adjective risky.','word-formation')]);
P('risqu','A spelling without the final accent for French risqué, from risquer “to risk”; risqu means slightly sexually suggestive in a humorous rather than shocking way.',C('risqu.s1','娱乐','The comedian told a risqu joke that made the audience blush but did not offend them.','喜剧演员讲了一个略带情色暗示的笑话，让观众脸红，却没有冒犯他们。','a risqu joke/story/remark','形容词：略带性暗示，通常以逗趣为主而非令人震惊。','joke is mildly suggestive.','娱乐'),M('The children’s book was called risqu because it contained no adult or suggestive references at all.','The late-night joke was called risqu because it included mild sexual innuendo.','完全没有成人或暗示内容的读物不符合此词义。','meaning'),[Q(1,'A risqu joke is…','slightly sexually suggestive, often humorously','violent and shocking in a nonsexual way','a riddle about a road','Risqu usually suggests mild adult humor.','meaning'),Q(1,'Which phrase is natural?','a risqu remark','a risquly remarking','a remark of risqunessly','Risqu is an adjective modifying remark.','grammar'),Q(1,'A playful adult joke hints at romance without being explicit. It may be…','risqu','rigid','rime','The tone is mildly suggestive rather than shocking.','context'),Q(1,'Risqu comes from the French word meaning…','risked','rinsed','ringed','The adjective is borrowed from French risqué.','word-formation')]);
P('rite','From Latin ritus “religious observance, custom,” of uncertain deeper origin; a rite is a traditional religious or public ceremony.',C('rite.s1','宗教','The community gathered at dawn for a rite marking the start of the harvest season.','社区成员黎明时聚集，举行仪式庆祝收获季节开始。','a religious/public rite; rite of passage','名词：传统宗教或公共仪式。','ceremony marks occasion.','宗教'),M('The community called the rite an everyday private task that involved no ceremony or tradition.','The community held a traditional rite to mark the start of the harvest season.','没有仪式或传统属性的普通私事不是rite。','meaning'),[Q(1,'A rite is…','a traditional religious or public ceremony','a casual ride to work','a ring around a cup','Rite names a ceremonial observance.','meaning'),Q(1,'Which phrase is natural?','a rite of passage','a right of passage only','a ritualistic passage to be a rite','A rite of passage is a traditional ceremony marking change.','collocation'),Q(1,'A community performs a traditional ceremony for a seasonal change. It is a…','rite','rind','ripple','The event is a ceremonial observance.','context'),Q(1,'Which word is often confused with rite but means “correct”?','right','rime','rider','Rite is ceremony; right means correct or entitlement.','distinction')]);
P('ritual','From Latin ritualis “relating to religious rites,” from ritus; ritual can mean a fixed-order ceremony, a habitual repeated action, or an adjective for ceremonial or routine actions.',[C('ritual.s1','宗教','The ceremony includes a ritual in which each family lights a candle.','仪式中有一项程序，每个家庭都要点燃一支蜡烛。','perform/observe a ritual; ritual of + event','名词：按固定顺序进行的一系列动作，常属宗教仪式。','families follow ceremony steps.','宗教'),C('ritual.s2','通用','Making tea before work is a quiet ritual that helps her focus.','上班前泡茶是她每天安静进行的惯例，有助于集中精神。','a daily/morning ritual; ritual of + habit','名词：总是以相同方式进行的习惯。','repeated personal routine.','通用'),C('ritual.s3','通用','The staff began the ritual check of the doors before closing the building.','员工开始了关楼前的例行门锁检查。','ritual greeting/check; ritual behavior','形容词：仪式性的，或不加思考地定期进行的。','check happens routinely.','通用')],M('Her morning ritual changed completely every day and had no repeated steps or habits.','Her morning ritual followed the same quiet steps before work each day.','每天都完全不同、没有重复的行为不能称为惯例。','meaning'),[Q(1,'A religious ritual is…','a series of actions performed in a fixed order','a single random movement','a risk of flooding','Sense 1 is a ceremony with set actions.','meaning'),Q(2,'Making tea every morning as a ritual is…','a repeated personal habit','a formal legal right','a sudden one-time event','Sense 2 is a regular routine.','context'),Q(3,'A ritual check before closing is…','an action performed routinely or ceremonially','a check that is never repeated','a small water wave','Ritual can modify an action done regularly.','meaning'),Q(1,'Which phrase is natural?','observe a religious ritual','observe a ritualistically of religion','ritualize of a religiously rite','Observe a ritual means carry out the set ceremony.','collocation')]);
P('ritualistic','From ritual + -istic, from Latin ritualis “relating to rites”; ritualistic means following a fixed ceremonial pattern, sometimes too strictly or without fresh thought.',C('ritualistic.s1','社会','The team’s ritualistic pre-match routine included the same song and warm-up every week.','球队赛前的仪式化惯例每周都包括同一首歌和热身活动。','ritualistic behavior/routine/ceremony','形容词：遵循固定仪式般的模式，有时显得过分程式化。','same set pattern repeats.','社会'),M('The flexible meeting changed its steps each week and was described as ritualistic because nothing ever repeated.','The team’s ritualistic routine repeated the same steps before every match.','没有重复固定模式就不符合ritualistic。','meaning'),[Q(1,'A ritualistic routine…','follows a fixed repeated pattern','changes randomly each time','is a legal entitlement','Ritualistic describes actions done according to a set pattern.','meaning'),Q(1,'Which phrase is natural?','a ritualistic ceremony','a ritualistically ceremony','a ritualistic of ceremony','Ritualistic is an adjective modifying ceremony.','grammar'),Q(1,'A person follows the same elaborate steps before every meal. The behavior is…','ritualistic','risky','riproarious','It follows a repeated, ceremonial-like pattern.','context'),Q(1,'Ritualistic is formed from the noun…','ritual','ritefully','rider','The adjective is based on ritual with -istic.','word-formation')]);
P('ritualize','From ritual + -ize, from Latin ritus “religious observance”; ritualize means turn an ordinary action into a ceremony or fix its steps into a repeated routine.',[C('ritualize.s1','通用','The family ritualized the annual reunion by lighting candles and sharing a written blessing.','这家人通过点蜡烛、分享书面祝词，把年度团聚变成了仪式。','ritualize an event/action','动词：把普通活动变成正式仪式。','gathering becomes ceremony.','通用'),C('ritualize.s2','通用','The coaches ritualized the warm-up so every player followed the same sequence.','教练把热身流程固定下来，让每位队员都按同一顺序进行。','ritualize a process/routine','动词：固定活动步骤，让人们反复照同一方式进行。','sequence becomes standardized.','通用')],M('The coaches ritualized the warm-up by allowing each player to invent a different order every day.','The coaches ritualized the warm-up by setting a sequence every player repeated.','每天都随意更换顺序与固定步骤相反。','meaning'),[Q(1,'The family ritualized its reunion by…','turning it into a ceremony with set actions','canceling every family gathering','repeating a road accident','Ritualize sense 1 makes an event ceremonial.','meaning'),Q(2,'Coaches ritualized a warm-up when they…','fixed its steps into a sequence players repeat','let everyone do something different each time','made the team ride a bus','Sense 2 describes standardizing repeated steps.','context'),Q(1,'Which phrase is natural?','ritualize the opening of the event','ritualize to the event openingly','ritualization the event into by','Ritualize takes the event being made ceremonial as its object.','grammar'),Q(1,'The suffix -ize in ritualize means…','make or cause to become','a person who performs','without','The verb means make something into a ritual or routine.','word-formation')]);
P('rival','From Latin rivalis “one using the same stream,” from rivus “stream”; rival is a competitor, to be equal to someone, or an adjective for competing groups.',[C('rival.s1','通用','The two runners have been rivals since they first competed in school.','这两名跑步者从学生时代首次同场竞技起就是竞争对手。','a rival to/of + person/team','名词：为同一目标相互竞争的人、队伍或公司。','runners compete.','通用'),C('rival.s2','书面','Few small theaters can rival the capital’s grand new opera house.','很少有小剧院能与首都那座宏伟的新歌剧院相媲美。','rival someone/something in + quality','动词：在质量或重要性上达到与某人某物相同的水平。','theater compares in scale.','书面'),C('rival.s3','商务','The rival companies announced competing phone plans on the same day.','相互竞争的公司在同一天公布了各自的手机套餐。','rival company/product/candidate','形容词：与另一人或团体竞争的。','companies compete in market.','商务')],M('The two rival firms signed an agreement to stop competing and operate as one company.','The two rival firms competed for the same customers.','停止竞争并合并与相互竞争的含义相反。','meaning'),[Q(1,'A rival runner is…','a competitor seeking the same prize','a coach who never competes','a passenger on the bus','Sense 1 names a competitor.','meaning'),Q(2,'Few theaters can rival the opera house means…','few can equal it in quality or scale','all are officially owned by it','the opera house is a riverbank','Rival as a verb means match or equal.','context'),Q(3,'Rival companies are companies that…','compete with one another','have ended competition permanently','share a single legal identity','Rival as an adjective describes competing organizations.','meaning'),Q(1,'Which phrase is natural?','a rival to the champion','a rival with the champion of at','a rivaling champion to the','Rival can be followed by to when naming a competitor.','grammar')]);
P('rivalry','From rival + -ry; rival is from Latin rivalis, originally one who used the same stream. Rivalry is competition for the same goal or a long unfriendly struggle.',[C('rivalry.s1','通用','The neighboring schools have a friendly rivalry over the annual science trophy.','邻近的两所学校围绕年度科学奖杯展开了友好的竞争。','rivalry between + people/groups; rivalry for + prize','名词：争夺同一目标的竞争。','schools seek same trophy.','通用'),C('rivalry.s2','通用','A long rivalry between the two nations continued despite several peace talks.','尽管举行了数次和谈，这两个国家之间长期的敌对仍在持续。','a bitter/long rivalry between + groups','名词：群体间长期不友好的竞争或对抗。','countries remain hostile.','通用')],M('The schools’ rivalry ended because they never competed for the trophy or any other shared goal.','The schools’ rivalry grew as both competed for the same trophy.','没有共同目标和竞争就没有此处所指的 rivalry。','meaning'),[Q(1,'A friendly rivalry over a trophy is…','competition between groups seeking the same prize','a formal robe ceremony','a river with no banks','Sense 1 is competition for a shared goal.','meaning'),Q(2,'A long rivalry between nations is…','an extended unfriendly struggle','a single quiet conversation','an easy resolution of every dispute','Sense 2 emphasizes prolonged hostility.','context'),Q(1,'Which phrase is correct?','a rivalry between the two schools','a rivalry to two schools between','rivalries the schools with of','Between identifies the competing sides.','grammar'),Q(1,'Rivalry is derived from…','rival','riverbed','rightful','The noun is formed from rival with -ry.','word-formation')]);
P('river','From Old French riviere “riverbank, river,” from Latin riparia “riverbank”; river is a broad natural flow of water, or figuratively a very large moving quantity.',[C('river.s1','地理','The river flows from the mountains through the plain and empties into the lake.','这条河从山中流出，穿过平原，最后汇入湖泊。','a river flows into/through + place','名词：流经陆地、注入海洋或湖泊的宽阔天然水流。','watercourse reaches lake.','地理'),C('river.s2','书面','A river of commuters poured through the station after the concert ended.','音乐会结束后，大批通勤者如潮水般涌过车站。','a river of + people/liquid','名词：大量流动的人或液体。','many people move continuously.','书面')],M('The river flowed from the mountain but consisted entirely of dry dust and contained no water.','The river flowed from the mountain as a wide stream of water.','没有水的尘土不是河流。','meaning'),[Q(1,'A river is…','a natural flow of water across land','a road for cars','a metal pin fastening two plates','Sense 1 is a watercourse.','meaning'),Q(2,'A river of commuters means…','a very large moving crowd','a small group sitting still','a waterless riverbed','The figurative use describes a large continuous flow of people.','context'),Q(1,'Which phrase is natural?','the river flows into the lake','the river flows to the lake into by','the lake rivers the flow','A river can flow into a lake.','grammar'),Q(1,'Which sentence uses river figuratively?','A river of fans left the arena.','The river flooded its banks.','We crossed the river by bridge.','In the first sentence river means a large stream of people.','meaning')]);
P('riverbank','From river + bank, with bank in the sense “raised edge of a watercourse”; a riverbank is the land along the side of a river.',C('riverbank.s1','地理','Willows grew along the riverbank where the current slowed near the bend.','河湾处水流减缓，柳树沿着河岸生长。','on/along the riverbank; riverbank of + river','名词：紧靠河流边缘的陆地。','trees grow at water’s edge.','地理'),M('The campers set up their tent in the middle of the river, not on either riverbank.','The campers set up their tent on the grassy riverbank beside the water.','河床中间的水里不是河岸。','meaning'),[Q(1,'A riverbank is…','the land along the side of a river','the deepest point under the water','a road beside a robot factory','Bank here means the river’s edge.','meaning'),Q(1,'Which phrase is natural?','walk along the riverbank','walk beneath the riverbank water','riverbank the river to along','Along describes movement beside the river’s edge.','grammar'),Q(1,'Willows grow next to the river on the…','riverbank','riverbed','roadbed','The riverbank is land at the river’s side.','context'),Q(1,'The compound riverbank combines river and…','bank','bed','rind','Bank means the raised edge beside a river.','word-formation')]);
P('riverbed','From river + bed, in the sense “bottom on which a river flows”; a riverbed is the channel bottom over which a river flows or used to flow.',C('riverbed.s1','地理','During the drought, the cracked riverbed was visible beneath the bridge.','干旱期间，桥下可以看到开裂的河床。','a dry/rocky riverbed; riverbed of + river','名词：河水流过或曾流过的河道底部。','channel bottom exposed.','地理'),M('The boat floated over the riverbed, which was the grassy land above the river’s banks.','The boat floated above the riverbed at the bottom of the channel.','河床在河道底部，不是河岸上方的草地。','meaning'),[Q(1,'A riverbed is…','the bottom of the channel where water flows','the land along the river’s side','a high ridge beside the river','Bed refers to the ground under the river.','meaning'),Q(1,'Which phrase is natural?','the riverbed was exposed during drought','the riverbed was the river’s upper bank','the riverbed floated above the water','A dry riverbed may be visible when water disappears.','context'),Q(1,'Which sentence uses riverbed correctly?','The fish swam close to the rocky riverbed.','The riverbed parked beside the street.','She wore a riverbed as a robe.','The riverbed is the bottom of the watercourse.','grammar'),Q(1,'The second part of riverbed means…','bottom or floor','outer edge','a person who competes','A bed is the bottom on which the river flows.','word-formation')]);
P('rivet','From French rivet, from river “fasten with a rivet,” of uncertain deeper origin; a rivet is a short metal pin fastening pieces together, or to hold someone’s attention completely.',[C('rivet.s1','工业','The metalworkers used a steel rivet to fasten the two plates together.','金属工人用一枚钢铆钉把两块金属板固定在一起。','a steel/aluminum rivet; rivet two pieces together','名词：用于固定两块金属的短金属销钉。','pin joins metal plates.','工业'),C('rivet.s2','通用','The documentary riveted the audience with its first-hand account of the rescue.','这部纪录片以救援亲历者的讲述牢牢吸引了观众。','rivet someone’s attention; be riveted by + story','动词：完全吸引某人的注意力。','audience watches closely.','通用')],M('The rivet held the metal plates together by leaving them completely separate and unattached.','The rivet held the metal plates together by fastening them through aligned holes.','未连接两块板不符合铆钉的用途。','meaning'),[Q(1,'A rivet in a metal frame is…','a short pin used to fasten pieces together','a long natural watercourse','a ceremonial garment','Sense 1 is a fastening pin.','meaning'),Q(2,'A documentary riveted its audience. The viewers were…','completely absorbed and attentive','bored and unable to hear it','divided by a rift','Sense 2 means hold attention completely.','context'),Q(1,'Which phrase is natural?','rivet two metal sheets together','rivet two sheets apart from together','rivet a sheet of attention','Rivet as a noun fastens parts together.','grammar'),Q(1,'The story riveted me means it…','held my attention completely','stole my wallet','made me a resident','The figurative verb means captivate.','meaning')]);
P('road','From Old English rād “riding, journey,” later the way traveled; road is a prepared way for vehicles or a figurative path to a result.',[C('road.s1','交通','The road was closed while workers repaired a damaged bridge.','工人维修受损桥梁期间，这条道路封闭了。','road to/through + place; on the road','名词：为汽车等车辆通行而修建的硬质路面。','vehicles cannot pass.','交通'),C('road.s2','书面','Regular practice is one road to greater confidence when speaking in public.','经常练习是提升公开演讲信心的一条途径。','a road to + goal/success','名词：达成某结果的一种途径或方法。','practice leads toward goal.','书面')],M('Workers called it a road for vehicles even though it was an unpaved field with no prepared route.','Workers called it a road after paving a route for vehicles.','没有修整成通行路线的田地不能据此称为公路。','meaning'),[Q(1,'A road is prepared mainly for…','vehicles to travel on','fish to swim beneath','people to wear as clothing','Sense 1 is a vehicle route.','meaning'),Q(2,'A road to greater confidence is…','a way of achieving that goal','a hard paved street only','a riverbank for residents','Sense 2 uses road figuratively as a path to a result.','context'),Q(1,'Which phrase is natural?','the road to the village','the road into the village’s resident to','a road of reaching at the village','A road can lead to a place.','grammar'),Q(1,'Which sentence uses road figuratively?','Patience is a road to understanding.','The road was paved last year.','The bus turned onto a road.','In the first sentence, road means a route to a goal.','meaning')]);
P('roadbed','From road + bed; bed means a supporting base. A roadbed is the prepared soil-and-stone foundation that supports a road or railway track.',C('roadbed.s1','工程','Engineers compacted the roadbed before laying the asphalt surface.','铺设沥青路面前，工程师压实了路基。','prepare/compact a roadbed; roadbed for + road','名词：支撑道路或铁路轨道的土石基础。','base is compacted first.','工程'),M('The crew laid the asphalt first and called the loose, unsupported surface beneath it the roadbed.','The crew compacted the soil-and-stone roadbed before laying asphalt on top.','没有支撑、铺路之后才处理的松土不是已准备好的路基。','meaning'),[Q(1,'A roadbed is…','the prepared base supporting a road','the painted line at the road’s center','a passenger’s seat','Bed here means a foundation.','meaning'),Q(1,'Which phrase is natural?','compact the roadbed','compact the roadbed after paving under it','roadbed the compactness at','The base is prepared and compacted before the surface is laid.','context'),Q(1,'Which construction item lies beneath asphalt?','roadbed','roadway','riverbank','Roadbed is the foundation layer under the road.','meaning'),Q(1,'Roadbed can support a road or…','railway track','a robe','a riverbank','The word covers the prepared base for roads and rail tracks.','collocation')]);
P('roadway','From road + way; way is a path or route. A roadway is the part of a street or road intended for vehicles, distinct from sidewalks or other areas.',C('roadway.s1','交通','A delivery van stopped in the roadway, blocking the lane for several minutes.','一辆送货车停在车行道上，堵住车道好几分钟。','in/on the roadway; roadway for + vehicles','名词：道路中供车辆行驶的部分，与人行道相区别。','van blocks vehicle lane.','交通'),M('The pedestrians walked in the roadway, which was the sidewalk reserved only for people on foot.','The pedestrians walked on the sidewalk beside the roadway used by vehicles.','roadway是车辆行驶部分，不是专供行人的人行道。','meaning'),[Q(1,'The roadway is the part of a street used by…','vehicles','only pedestrians on a sidewalk','boats on a river','Sense 1 distinguishes it from the pavement/sidewalk.','meaning'),Q(1,'Which phrase is natural?','park outside the roadway','park in the roadway sidewalk for walking only','roadway the vehicle at','A vehicle may stop in or block the roadway.','grammar'),Q(1,'A cyclist moves in the lane beside the sidewalk. The cyclist is on the…','roadway','riverbed','roadbed only','The roadway is the vehicle-use portion of the street.','context'),Q(1,'Roadway combines road with…','way','rind','rival','Way means a path or route.','word-formation')]);
P('roam','From Old English ramian “roam,” of uncertain deeper origin; roam means move around without a fixed plan, especially for pleasure, or range freely over a wide area.',[C('roam.s1','通用','We roamed through the old market until we found a small tea shop.','我们在老市场里随意逛着，直到找到一家小茶馆。','roam around/through + place','动词：没有固定计划地四处走动，常为消遣。','walkers wander freely.','通用'),C('roam.s2','自然','Wild horses roam across the grassland in search of water.','野马在草原上自由活动，寻找水源。','animals roam over/across + area','动词：动物在广阔区域内自由活动。','horses range over land.','自然')],M('The wild horses roamed across the fenced paddock while remaining tied to one post the entire time.','The wild horses roamed freely across the open grassland.','始终拴在原地与自由漫游相反。','meaning'),[Q(1,'Tourists roamed through the market. They…','walked around without a fixed plan','followed a strict single-file route','repaired the market road','Sense 1 is unplanned wandering.','meaning'),Q(2,'Wild horses roam across grassland. They…','move freely over a wide area','stay tied to one post','reproduce in a laboratory','Sense 2 describes animals ranging freely.','context'),Q(1,'Which phrase is natural?','roam around the city','roam to the city with a fixed appointment','roam the city by staying home','Roam around introduces the place wandered through.','grammar'),Q(1,'A person wanders through streets for pleasure. The person…','roams','rinses','rivals','Roam means move around without a set plan.','meaning')]);
P('roar','From Old English rarian, of Germanic origin; roar is a loud deep sound or means make that sound, describe a crowd/engine’s continuous noise, or laugh loudly.',[C('roar.s1','通用','The lion roared when the keeper approached the enclosure.','饲养员走近围栏时，狮子吼叫起来。','a lion roars; roar at + person','动词：像狮子或愤怒的人那样发出低沉的巨响。','animal vocalizes loudly.','通用'),C('roar.s2','通用','The engines roared as the planes accelerated down the runway.','飞机沿跑道加速时，发动机发出轰鸣声。','engines/crowds roar; roar with laughter','动词：人群、发动机或火焰持续发出巨大声响，也可指大笑。','engines make continuous noise.','通用'),C('roar.s3','通用','A roar of applause filled the hall after the final song.','最后一首歌结束后，雷鸣般的掌声充满大厅。','a roar of + sound/laughter','名词：低沉、响亮的声音或喧闹声。','crowd creates loud sound.','通用')],M('The lion roared silently without producing any sound or vibration.','The lion roared with a deep, loud sound that echoed through the enclosure.','完全无声与吼叫相矛盾。','meaning'),[Q(1,'A lion roars when it…','makes a loud deep sound','moves quietly without sound','rinses its food','Sense 1 is an animal’s loud vocal sound.','meaning'),Q(2,'The engines roared down the runway means they…','made a continuous loud noise','were silent and switched off','laughed at a joke','Sense 2 includes engine noise.','context'),Q(3,'A roar of applause is…','a loud wave of sound from the crowd','a quiet single clap','an animal’s riverbank','Roar as a noun names a loud sound.','meaning'),Q(2,'“They roared with laughter” means they…','laughed loudly','made an animal growl','drove cars on the roadway','Roar can describe loud laughter.','context')]);
P('roast','From Old French rostir, of Germanic origin; roast means cook meat or vegetables in an oven or over fire, the food or meal cooked that way, or cooked by roasting.',[C('roast.s1','餐饮','We roasted carrots and onions in the oven with olive oil and herbs.','我们用橄榄油和香草在烤箱里烤胡萝卜和洋葱。','roast meat/vegetables in an oven','动词：在烤箱或明火上烹调肉类或蔬菜。','vegetables cooked in oven.','餐饮'),C('roast.s2','餐饮','The family served a roast with potatoes for Sunday lunch.','这家人周日午餐供应烤肉和土豆。','a beef/lamb roast; a Sunday roast','名词：烤制的一块肉或以烤肉为主的一餐。','meal includes roasted meat.','餐饮'),C('roast.s3','餐饮','The restaurant offers roast chicken with seasonal vegetables.','这家餐厅供应烤鸡配时令蔬菜。','roast chicken/potatoes','形容词：经过烘烤或明火烤制的。','chicken cooked by roasting.','餐饮')],M('They roasted the carrots by boiling them in water and never exposing them to an oven or fire.','They roasted the carrots in the oven until they became tender and browned.','水煮没有使用烘烤方式。','distinction'),[Q(1,'To roast vegetables is to…','cook them in an oven or over a fire','wash them quickly with clean water','freeze them raw','Sense 1 is a cooking method.','meaning'),Q(2,'A Sunday roast is…','a meal or piece of meat cooked by roasting','a reservation at noon only','a river of vegetables','Sense 2 is a roast meal or roast meat.','context'),Q(3,'Roast chicken describes chicken that is…','cooked by roasting','uncooked and frozen','rinsed only','Sense 3 uses roast adjectivally.','meaning'),Q(1,'Which phrase is natural?','roast potatoes in the oven','roast potatoes with no heat or cooking','roasting potatoes in a riverbed','Roasting uses oven heat or open fire.','grammar')]);
P('rob','From Old French rober “steal, plunder,” probably from a Germanic source; rob means unlawfully take property from a person or place, or figuratively deprive someone of a quality or chance.',[C('rob.s1','法律','Two masked thieves robbed the corner shop shortly before closing.','两名蒙面窃贼在商店即将关门前抢劫了街角便利店。','rob a person/place of + property','动词：非法从人或地点夺取钱财或财物。','thieves take property.','法律'),C('rob.s2','书面','The long delay robbed the children of an afternoon at the beach.','漫长的延误使孩子们失去了去海滩度过下午的机会。','rob someone of + chance/quality','动词：剥夺某人重要品质或机会。','delay takes opportunity away.','书面')],M('The thieves robbed the shop by returning every item, leaving all money untouched, and taking nothing.','The thieves robbed the shop by unlawfully taking cash and merchandise.','没有拿走任何东西就没有发生抢劫。','meaning'),[Q(1,'Thieves robbed a shop when they…','unlawfully took property from it','returned all its goods','rescheduled its opening time','Sense 1 is theft from a place.','meaning'),Q(2,'The delay robbed the children of an afternoon means it…','deprived them of that opportunity','gave them extra time at the beach','ripped their clothing','Sense 2 is figurative deprivation.','context'),Q(1,'Which construction is correct?','rob the store of its cash','rob the store from its cash of','rob cash to the store','Rob may take a person or place, with of marking what is taken.','grammar'),Q(1,'Which sentence uses rob figuratively?','The storm robbed us of our picnic.','The thief robbed the store.','The robber entered the bank.','The storm took away an opportunity, not property.','meaning')]);
P('robber','From rob + -er, from Old French rober “steal”; a robber is someone who steals from a bank, shop, or person, often using force.',C('robber.s1','法律','The robber took cash from the shop and fled before police arrived.','强盗从商店拿走现金，在警察赶到前逃走了。','a bank/shop robber; armed robber','名词：从银行、商店或个人处实施抢劫的人。','person steals money.','法律'),M('The robber returned all the money and was hired by the shop as its cashier.','The robber stole money from the shop and fled.','归还钱并受雇作收银员并非抢劫者的行为。','meaning'),[Q(1,'A robber is…','someone who steals from a person or place','a person who repairs roadbeds','a resident who never leaves home','Robber names a person who commits robbery.','meaning'),Q(1,'Which phrase is natural?','an armed robber','a robbery personer','a robber of to shop','Armed modifies robber to describe the crime.','grammar'),Q(1,'Someone takes cash from a bank by force. That person is a…','robber','rider','rival','The person has robbed the bank.','context'),Q(1,'Robber is formed from rob plus…','-er','-ity','-ous','The suffix -er names the person who performs the action.','word-formation')]);
P('robbery','From rob + -ery, from Old French rober “steal”; robbery is the crime of taking property from a person or place using force or threat.',C('robbery.s1','法律','The police investigated the robbery after witnesses reported a threat at the cash desk.','目击者报告收银台有人受到威胁后，警方调查了这起抢劫案。','commit/report/investigate a robbery','名词：以暴力或威胁从人或地点夺取财物的犯罪。','threat accompanies theft.','法律'),M('Police called it a robbery even though no one threatened anyone and nothing was taken.','Police called it a robbery after cash was taken under threat.','没有威胁也没有财物被拿走，不符合抢劫罪的描述。','meaning'),[Q(1,'Robbery is…','the crime of taking property using force or threat','a fair sale of goods','a road repair','Robbery involves theft with force or threat.','meaning'),Q(1,'Which phrase is natural?','report a robbery to police','report a robbery with no theft or threat','robberying the police report','One reports a robbery to police.','grammar'),Q(1,'A person threatens a shopkeeper and takes cash. This is…','robbery','residence','rivalry','The theft uses a threat, fitting robbery.','context'),Q(1,'Which verb commonly combines with robbery?','commit','roam','roast','One commits a robbery.','collocation')]);
P('robe','From Old French robe “garment,” from a Germanic word meaning “spoils, clothing”; a robe is a long loose garment worn at home or for formal or religious occasions.',[C('robe.s1','家居','She put on a soft robe after stepping out of the bath.','她洗完澡后穿上了一件柔软的睡袍。','a bath/dressing robe; wear a robe','名词：在家放松或睡前穿的宽松长袍。','loose garment for home.','家居'),C('robe.s2','宗教','The judge wore a black robe during the formal ceremony.','正式仪式上，法官穿着黑色法袍。','a judge’s/priest’s robe','名词：法官、牧师或其他官员在礼仪场合穿的长袍。','official garment.','礼仪')],M('After bathing, she put on a stiff uniform with no loose fabric and called it a robe.','After bathing, she put on a loose robe to relax at home.','紧身制服不是宽松长袍。','meaning'),[Q(1,'A bath robe is…','a long loose garment worn at home','a metal pin for a road sign','a bird with an orange breast','Sense 1 is casual home clothing.','meaning'),Q(2,'A judge’s robe is worn…','for formal or official occasions','to ride a bicycle','to roast food','Sense 2 is ceremonial clothing.','context'),Q(1,'Which phrase is natural?','wear a robe after bathing','wear a robe in the riverbed to swim','robe a bath with a garment','A robe is worn as clothing after bathing.','grammar'),Q(1,'Which garment is closest to a robe?','a loose long gown','a tight short belt','a helmet','A robe is a long, loose garment.','meaning')]);
P('robin','Named in English with Robin, a diminutive of Robert, as a familiar personal name; robin is a small bird with a red or orange breast, either the European robin or American robin.',C('robin.s1','动物','A robin pulled a worm from the damp lawn after the rain.','雨后，一只知更鸟从潮湿的草坪上叼出一条蚯蚓。','a robin with a red/orange breast','名词：欧亚鸲或胸部带红橙色的美洲旅鸫。','bird searches for food.','动物'),M('The robin was a large fish with fins and gills living underwater.','The robin was a small bird with a reddish breast searching for food on the lawn.','鱼不是这种有红橙色胸部的鸟。','distinction'),[Q(1,'A robin is…','a small bird with a reddish breast','a long loose ceremonial garment','a kind of road surface','The source sense identifies the bird.','meaning'),Q(1,'Which phrase is natural?','a robin on the garden lawn','a robin fish with gills','robin the lawn into a bird','Robins are birds commonly seen foraging on lawns.','context'),Q(1,'A bird with an orange breast hops beside a garden path. It may be a…','robin','rival','robot','The robin is a small reddish- or orange-breasted bird.','meaning'),Q(1,'The English bird name robin is associated with…','the familiar name Robin','the Latin word for riverbed','the act of roasting','The bird name developed from a familiar personal name.','word-formation')]);
P('robot','From Czech robot “forced labor,” popularized by Karel Čapek’s 1920 play R.U.R.; a robot is a machine that performs tasks, sometimes with a human-like form, or a person acting mechanically.',[C('robot.s1','科技','The factory robot lifted each metal panel and placed it on the assembly line.','工厂机器人抬起每块金属板，并把它放到装配线上。','an industrial/service robot; robot arm','名词：能移动并执行工作的机器，有些外形近似人。','machine performs task.','科技'),C('robot.s2','口语','After working three night shifts, he felt like a robot and barely noticed the conversation.','连上三个夜班后，他觉得自己像机器人一样机械，几乎没注意到谈话。','act/work like a robot','名词比喻：行动机械、缺少思考或情感的人。','person behaves automatically.','口语')],M('The factory robot was a human employee who performed no tasks and remained motionless all day.','The factory robot was a machine that repeatedly moved panels along the production line.','不执行任务的静止人类员工不是机器人。','meaning'),[Q(1,'A factory robot is…','a machine that performs work','a bird with an orange breast','a person’s legal right','Sense 1 is a task-performing machine.','meaning'),Q(2,'He felt like a robot after three night shifts means he felt…','mechanical and barely responsive','fully rested and emotionally lively','like a machine on a roadway','Sense 2 is figurative for automatic behavior.','context'),Q(1,'Which phrase is natural?','an industrial robot','a robotic of industry person','robotically industry device','Robot is a noun naming the machine.','grammar'),Q(1,'The word robot entered English from…','Czech','Old English','Latin river words','The term comes from Czech robot, “forced labor.”','word-formation')]);
P('robotic','From robot + -ic; robot comes from Czech robot “forced labor.” Robotic means related to robots or stiff and lacking human warmth.',[C('robotic.s1','技术','The robotic arm placed each component exactly on the circuit board.','机械臂把每个部件精确地放到了电路板上。','robotic arm/system/process','形容词：与机器人有关或由机器人完成的。','machine arm performs task.','技术'),C('robotic.s2','性格','His robotic delivery made the heartfelt speech sound cold and unnatural.','他机械呆板的表达让这篇真挚的演讲听起来冷漠而不自然。','a robotic voice/manner/movement','形容词：动作或说话僵硬、缺少人的温情。','speech sounds mechanical.','性格')],M('Her robotic voice sounded warm, spontaneous, and full of natural emotion.','Her robotic voice sounded stiff and mechanical, with little natural emotion.','自然温暖、富有情感与机械呆板相反。','meaning'),[Q(1,'A robotic arm is…','a machine-related arm that performs programmed work','a bird’s curved feather','a human arm in a robe','Sense 1 relates to robots or robot operation.','meaning'),Q(2,'A robotic delivery sounds…','stiff and lacking human warmth','spontaneous and emotionally expressive','like a river roaring','Sense 2 is figurative for mechanical behavior.','context'),Q(1,'Which phrase is natural?','a robotic voice','a robotically voice','a voice roboticity','Robotic is an adjective modifying voice.','grammar'),Q(1,'Robotic is formed from…','robot + -ic','robe + -ly','roar + -ous','The adjective suffix -ic forms robotic from robot.','word-formation')]);
P('robust','From Latin robustus “strong, oak-like,” from robur “oak, strength”; robust means strong and healthy or sturdily built and unlikely to fail under stress.',[C('robust.s1','通用','The robust hiker recovered quickly after the long climb.','这位体格强健的徒步者在长时间攀登后很快恢复了体力。','a robust person/health','形容词：强壮、健康、有活力的。','person recovers well.','通用'),C('robust.s2','科技','The robust case protected the tablet during repeated drops and heavy rain.','这个结实耐用的保护壳在多次跌落和大雨中保护了平板电脑。','a robust system/design/case','形容词：结构结实，能够承受损坏或变化而不易失效。','case withstands stress.','科技')],M('The robust case failed on its first light tap and offered no protection from rain.','The robust case survived repeated drops and kept rain away from the tablet.','轻触就损坏且无法防雨，说明外壳不结实。','meaning'),[Q(1,'A robust hiker is…','strong and healthy','weak and constantly ill','a rider without a bicycle','Sense 1 describes a person’s strength and health.','meaning'),Q(2,'A robust tablet case…','is sturdy and withstands stress','breaks immediately under light use','is a long river','Sense 2 concerns durability and reliability.','context'),Q(1,'Which phrase is natural?','a robust design','a robustly design','a design robustnessly','Robust is an adjective modifying design.','grammar'),Q(1,'Which word is closest to robust in the construction sense?','sturdy','fragile','riproarious','A robust construction is strong and unlikely to fail.','meaning')]);
P('rock','From Old English rocc for a stone; the verb meaning sway is Germanic, while the music sense is a shortening of rock and roll. Rock can also mean move back and forth.',[C('rock.s1','地理','A large rock blocked the hiking trail after the storm.','暴风雨过后，一块大岩石挡住了徒步小径。','a rock on/in + place; rock formation','名词：构成地表的坚硬石头或一块石块。','stone blocks path.','地理'),C('rock.s2','音乐','The band played energetic rock with electric guitars and a strong beat.','乐队用电吉他和强劲节拍演奏了充满活力的摇滚乐。','rock music; play/listen to rock','名词：以强节拍和吉他为特色的一类流行音乐。','band uses guitars.','音乐'),C('rock.s3','通用','The nurse rocked the baby gently until he fell asleep.','护士轻轻摇晃婴儿，直到他睡着。','rock gently/back and forth; rock someone to sleep','动词：前后轻轻摆动；也可指震惊某人。','baby moves side to side.','通用')],M('The nurse rocked the baby by holding him completely still without moving him.','The nurse rocked the baby gently back and forth until he fell asleep.','一动不动不符合摇晃的动作义。','meaning'),[Q(1,'A rock blocking a trail is…','a piece of hard stone','a kind of music','a baby’s cradle movement','Sense 1 is stone.','meaning'),Q(2,'The band played rock. It played…','popular music with a strong beat and guitars','a geological formation','a ceremonial robe','Sense 2 is a music genre.','context'),Q(3,'She rocked the baby to sleep. She…','moved the baby gently back and forth','made the baby into stone','played the phone’s ring','Rock as a verb can mean sway gently.','meaning'),Q(1,'Which phrase is natural?','a rock formation','a rock music formed from stones only','rock the formation of music at','Rock can modify formation for geological features.','grammar')]);
P('rocket','From Italian rocchetta “small spindle,” diminutive of rocca; a rocket is propelled by hot gas, or as a verb to rise or increase very quickly.',[C('rocket.s1','科技','The research rocket carried a weather instrument above the atmosphere.','这枚科研火箭把一台气象仪器送到了大气层上方。','launch/fire a rocket; rocket into space','名词：靠高温气体喷射向上推进的筒状飞行器或武器。','vehicle is propelled upward.','科技'),C('rocket.s2','经济','The price of heating oil rocketed after the supply route was blocked.','供货线路被封锁后，取暖油价格迅速飙升。','prices rocket; rocket to/by + amount','动词：数量或水平迅速上升。','price rises rapidly.','经济')],M('The price rocketed downward slowly by one cent over ten years.','The price rocketed upward by 40 percent in a single week.','缓慢微降不符合迅速上升的用法。','meaning'),[Q(1,'A research rocket is…','a vehicle propelled upward by hot gas','a metal pin holding plates together','a small bird','Sense 1 names a propulsion vehicle.','meaning'),Q(2,'Prices rocketed after the supply shortage. They…','increased very quickly','fell slowly over many years','were turned into robots','Rocket as a verb means rise rapidly.','context'),Q(1,'Which phrase is natural?','launch a rocket into space','rocket a space into launch','launch a rocket by rowing it','Rockets are launched and propelled into space.','collocation'),Q(1,'Which sentence uses rocket as a verb?','Costs rocketed after the tax changed.','The rocket stood on the launchpad.','A rocket is a vehicle.','In the first sentence, rocketed means increased rapidly.','grammar')]);
P('rocky','From rock + -y; rock as a stone comes from Old English rocc. Rocky means covered with rocks, or unsteady and full of difficulties.',[C('rocky.s1','地理','A narrow rocky path wound between the cliffs and the sea.','一条狭窄多岩石的小路蜿蜒在悬崖与海洋之间。','rocky ground/coast/path','形容词：被岩石覆盖或由岩石构成的。','stones cover path.','地理'),C('rocky.s2','通用','The project had a rocky start, with missed deadlines and unclear instructions.','这个项目开局不顺，期限被错过，说明也不清楚。','a rocky start/relationship/period','形容词：不稳定、困难重重的。','early problems disrupt progress.','通用')],M('The project had a rocky start because every deadline was met easily and all instructions were clear.','The project had a rocky start because deadlines were missed and instructions were unclear.','顺利且清晰的开局不是困难重重。','meaning'),[Q(1,'A rocky path is…','covered with stones','perfectly smooth and paved','a river full of fish eggs','Sense 1 is literal.','meaning'),Q(2,'A rocky start to a project is…','difficult and unstable','easy and trouble-free','a start on a mountain ridge only','Sense 2 is figurative for difficulties.','context'),Q(1,'Which phrase is natural?','a rocky coastline','a rockily coastline','a coastline rockying','Rocky is an adjective describing the coast.','grammar'),Q(1,'Which sentence uses rocky figuratively?','Their relationship had a rocky year.','The road crossed rocky ground.','A rocky beach had many stones.','In the first sentence rocky means troubled or unstable.','meaning')]);
P('rococo','From French rococo, an 18th-century art term probably influenced by rocaille “rockwork” and baroque; rococo is an ornate artistic style or excessively elaborate decoration.',[C('rococo.s1','艺术','The palace’s rococo rooms feature carved shells, gold trim, and curved furniture.','宫殿的洛可可风格房间有雕刻贝壳、金色饰边和弯曲家具。','rococo art/architecture/interior','名词：流行于十八世纪、装饰繁复的艺术和建筑风格。','room displays historic style.','艺术'),C('rococo.s2','通用','The proposal’s rococo wording buried a simple idea under too many flourishes.','提案华而不实的措辞用过多修饰掩盖了一个简单想法。','rococo decoration/language','形容词：细节过多、过分华丽的。','wording is overly ornate.','通用')],M('The room was rococo because it was plain, undecorated, and entirely free of ornamental detail.','The room was rococo because it was covered in elaborate curves and decorative details.','朴素且无装饰与繁复华丽相反。','meaning'),[Q(1,'Rococo as an art style is…','an ornate style popular in the 1700s','a modern road-building method','a type of bird','Sense 1 refers to the historical art style.','meaning'),Q(2,'Rococo wording is…','overly elaborate and full of decorative details','plain and direct with no flourishes','a verb meaning to roll','Sense 2 is the adjective’s figurative use.','context'),Q(1,'Which phrase is natural?','rococo architecture','rococoingly architecture','architecture a rococo of','Rococo can describe an architectural style.','grammar'),Q(1,'A highly ornamented eighteenth-century interior is…','rococo','robust','robotic','The style is characterized by elaborate decoration.','context')]);
P('rod','From Old English rodd “rod, pole,” of uncertain deeper origin; a rod is a long, thin, straight piece of wood, metal, or plastic, or a fishing pole.',[C('rod.s1','通用','The surveyor placed a metal rod into the ground to mark the boundary.','测量员把一根金属杆插进地里，标出边界。','a metal/wooden rod; rod of + material','名词：木、金属或塑料制成的细长直条。','long straight bar.','通用'),C('rod.s2','运动','She packed her fishing rod before driving to the lake.','她开车去湖边前收好了钓竿。','a fishing rod; rod and reel','名词：用于钓鱼的长杆。','angler carries pole.','运动')],M('The surveyor marked the boundary with a perfectly round piece of cloth, not a long thin bar.','The surveyor marked the boundary with a long metal rod.','圆布片不是细长直杆。','meaning'),[Q(1,'A metal rod is…','a long thin straight bar','a small curl of hair','a large crowd of people','Sense 1 is a straight bar.','meaning'),Q(2,'A fishing rod is used to…','catch fish with a line','pave a roadbed','perform a rodeo on foot only','Sense 2 names the fishing pole.','context'),Q(1,'Which phrase is natural?','a rod of iron','a rod of ironing by round','iron rod to a fishing','Rod can be followed by of plus the material.','grammar'),Q(1,'Which person would most likely carry a rod?','an angler','a robin','a robber','A fishing rod is equipment for fishing.','context')]);
P('rodent','From Latin rodere “gnaw,” with -ent; a rodent is a mammal such as a rat, mouse, or squirrel with sharp front teeth for gnawing.',C('rodent.s1','自然','The field researcher identified the small animal as a rodent by its sharp front incisors.','田野研究人员根据这只小动物锋利的门齿认出它是啮齿动物。','a rodent such as + rat/mouse/squirrel','名词：有适于啃咬的锋利前齿的小型哺乳动物。','incisors are prominent.','自然'),M('The researcher identified the rabbit as a rodent because it had a beak and feathers.','The researcher identified the rat as a rodent because it had sharp front teeth for gnawing.','有喙和羽毛的鸟类特征不能支持啮齿动物分类。','distinction'),[Q(1,'A rodent is a mammal such as…','a rat','a robin','a crocodile','Rats are rodents with gnawing front teeth.','meaning'),Q(1,'Rodents are recognized in part by…','sharp front incisors','feathers and a beak','gills and fins','Their incisors are adapted for gnawing.','context'),Q(1,'Which phrase is natural?','a small rodent in the field','a rodent with feathers','a rodent of an eagle','A field rodent may be a mouse or squirrel.','grammar'),Q(1,'Rodent comes from a Latin verb meaning…','gnaw','roar','ride','Rodents are named for their gnawing teeth.','word-formation')]);
P('rodeo','From Spanish rodeo “roundup,” from rodear “surround”; a rodeo is a public contest or exhibition of cowboy skills such as roping cattle and riding bucking horses.',C('rodeo.s1','体育','At the rodeo, riders competed to stay on bucking horses for as long as possible.','牛仔竞技会上，骑手们比赛看谁能在烈马上坚持更久。','attend/compete in a rodeo; rodeo event','名词：展示套牛、骑烈马等牛仔技能的公开比赛或表演。','contest features cowboy skills.','体育'),M('The rodeo consisted of a quiet library reading with no horses, cattle, riders, or competition.','The rodeo featured riders, roping events, and bucking horses.','没有牛仔项目或比赛的阅读会不是牛仔竞技。','meaning'),[Q(1,'A rodeo showcases…','cowboy skills such as roping and riding','robot design and programming','a formal court proceeding','Rodeos feature cowboy contests.','meaning'),Q(1,'At a rodeo, a rider may try to…','stay on a bucking horse','reside in a riverbed','roast a meal in an oven','Riding a bucking horse is a standard rodeo event.','context'),Q(1,'Which phrase is natural?','compete in a rodeo','compete on a rodeo to','rodeo the competition into','One competes in the event.','grammar'),Q(1,'Which setting is most likely to host a rodeo?','an arena with horses and cattle','a quiet archive with no animals','a roadbed construction site','Rodeos are public cowboy skill events.','meaning')]);
P('roe','From Old Norse hrogn for fish eggs; the deer sense is from a Germanic animal name. Roe is fish eggs or a small Eurasian deer.',[C('roe.s1','饮食','The chef served salmon roe on toast with lemon and fresh herbs.','厨师把三文鱼鱼卵配上柠檬和新鲜香草，放在吐司上。','fish/salmon roe; roe of + fish','名词：雌鱼体内的卵，也可指雄鱼的精子。','fish eggs served as food.','饮食'),C('roe.s2','动物','A roe deer crossed the woodland path at dawn and vanished among the trees.','一只狍在黎明时穿过林间小路，消失在树丛中。','roe deer; a roe in + habitat','名词：欧洲狍，一种小型鹿。','small deer enters woods.','动物')],M('The chef served fish roe, which consisted of tiny pieces of antler from a small deer.','The chef served fish roe, which consisted of fish eggs.','鱼卵不是鹿角碎片。','distinction'),[Q(1,'Salmon roe is…','the fish’s eggs','a small deer','a kind of road','Sense 1 is a food made from fish eggs.','meaning'),Q(2,'A roe deer is…','a small Eurasian deer','a fish egg','a machine that rolls metal','Sense 2 is the animal.','context'),Q(1,'Which phrase is natural?','serve roe on toast','serve a roe deer’s eggs as fish roe','roe the toast into eggs','Fish roe may be served as food.','grammar'),Q(1,'The word roe has two source senses referring to…','fish eggs and a small deer','a river and its bank','a song and its singer','The entry distinguishes roe as fish eggs and roe deer.','meaning')]);
P('rogue','From 16th-century English rogue, origin uncertain; rogue is a dishonest or uncontrolled person, or an animal living apart from its group and not under control.',[C('rogue.s1','口语','The rogue cheated customers by charging them twice and pocketing the extra money.','这个无赖向顾客重复收费，把多收的钱据为己有。','a rogue trader/person; a rogue’s behavior','名词：行为不诚实或不受约束的人。','person acts dishonestly.','口语'),C('rogue.s2','自然','A rogue elephant left the herd and damaged several farms near the forest.','一头离群且不受控制的大象离开象群，破坏了森林附近的几处农场。','a rogue animal/wave/state','名词/形容词：脱离群体或不受控制的动物等。','animal leaves herd.','自然')],M('The rogue trader was honest, followed every rule, and never cheated a customer.','The rogue trader repeatedly cheated customers and ignored the rules.','守信守规与无赖式欺诈相反。','meaning'),[Q(1,'A rogue trader is…','a dishonest or uncontrolled person','a highly reputable seller','a fish egg','Sense 1 is a person who behaves badly.','meaning'),Q(2,'A rogue elephant is one that…','has separated from its herd and is uncontrolled','is safely guided with its group','is a type of rodent','Sense 2 describes an animal apart from its group.','context'),Q(1,'Which phrase is natural?','a rogue wave struck the coast','a rogue wave followed every rule','a rogue of wave in the coast','Rogue can describe something uncontrolled or out of pattern.','grammar'),Q(1,'Which word is closest to rogue as a person?','scoundrel','saint','rider','A rogue is often a dishonest person.','meaning')]);
P('role','From French rôle “part played by an actor,” from Old French rolle “roll” of manuscript; role is an actor’s character or a person’s function and responsibility in a group.',[C('role.s1','戏剧','She played the role of the judge in the school production.','她在学校演出中扮演法官这个角色。','play/take the role of + character','名词：演员在戏剧或电影中扮演的角色。','actor performs character.','戏剧'),C('role.s2','通用','Parents have an important role in helping children build healthy habits.','父母在帮助孩子养成健康习惯方面发挥着重要作用。','a role in + activity; role of + person','名词：某人在团体或情境中承担的功能或职责。','parents contribute.','通用')],M('She played the role of the judge by staying offstage and never appearing in the production.','She played the role of the judge by appearing in the production as that character.','从未出场不符合出演角色。','meaning'),[Q(1,'An actor’s role is…','the character the actor plays','the actor’s legal entitlement','the theater’s roof','Sense 1 is a part in a performance.','meaning'),Q(2,'A parent’s role in healthy habits is…','the function or responsibility the parent has','a character in a school play','a repeated ceremony only','Sense 2 concerns a function in a situation.','context'),Q(1,'Which phrase is natural?','play the role of a doctor','play role to a doctor of','a role playing the doctor by at','The common pattern is play the role of + character.','grammar'),Q(1,'A team member who coordinates schedules has a…','role in the team','rivalry in the team only','robin on the team','Role can name a function or responsibility.','meaning')]);
P('roll','From Old French roller “turn over,” with Germanic roots; roll means move by turning or on wheels, shape something into a tube or ball, or a list, small loaf, or rolling movement.',[C('roll.s1','通用','The marble rolled down the ramp and stopped beside the door.','弹珠沿斜坡滚下来，停在门边。','roll down/across + surface','动词：通过连续翻转或借助轮子移动。','marble turns as it moves.','通用'),C('roll.s2','通用','Roll the dough into a thin cylinder before cutting it into strips.','把面团擀成细长的圆筒形，再切成条。','roll something into + shape; roll out dough','动词：把某物卷成筒状或球状。','dough changes shape.','通用'),C('roll.s3','通用','The clerk checked every name on the school roll before the trip.','出发前，职员核对了学校名册上的每个名字。','the electoral/class/attendance roll; a bread roll','名词：正式名单，也指小圆面包或滚动动作。','clerk checks list.','通用')],M('The marble rolled down the ramp by remaining fixed in one place without turning or moving.','The marble rolled down the ramp as it turned and traveled over the surface.','固定不动不符合滚动。','meaning'),[Q(1,'The marble rolled down the ramp. It…','moved while turning over','was shaped into a ball','appeared on the class list','Sense 1 means move by turning.','meaning'),Q(2,'Roll the dough into a cylinder means…','shape it into a long tube','put it on the school roll','bake it immediately','Sense 2 means form something into a shape.','context'),Q(3,'The school roll is…','an official list of names','a small stone moving on a ramp','a wheel used to flatten roads','Sense 3 uses roll as a list.','meaning'),Q(3,'Which sentence uses roll to mean bread?','She bought a warm bread roll.','The ball rolled away.','The teacher called the roll.','In the first sentence roll is a small loaf.','context')]);
P('roller','From roll + -er; roll comes through Old French roller “turn over.” A roller is a heavy cylinder used to flatten a surface or a smaller turning cylinder such as a hair curler.',[C('roller.s1','工具','A road roller flattened the fresh gravel before workers added asphalt.','道路压路机在工人铺沥青前压平了新铺的碎石。','a road/steam roller; roll with a roller','名词：用于压平、压实或碾碎表面的重型圆筒。','machine flattens gravel.','工具'),C('roller.s2','外貌','She put a roller in each section of her hair before the party.','派对前，她在每一缕头发上都卷了一个卷发筒。','hair rollers; a small roller for + task','名词：转动的小圆筒，也可指卷发筒。','cylinders curl hair.','外貌')],M('The road roller left the gravel loose and uneven because it never pressed the surface.','The road roller pressed and leveled the gravel surface.','没有压实表面不符合压路机的用途。','meaning'),[Q(1,'A road roller is…','a heavy cylinder that flattens a surface','a list of student names','a riverbank bird','Sense 1 is construction equipment.','meaning'),Q(2,'Hair rollers are used to…','curl sections of hair','pave a road','fasten steel plates','Sense 2 is a small cylinder for curling hair.','context'),Q(1,'Which phrase is natural?','flatten the gravel with a roller','roller the gravel by a river','flatten gravel with a hair roller only','A road roller presses a surface flat.','grammar'),Q(1,'A roller is named from which verb?','roll','roam','rob','A roller is a device that rolls or turns.','word-formation')]);
P('romance','From Old French romanz, originally a vernacular narrative and later a tale of love or adventure; romance can mean a love relationship, such a story or atmosphere, or to pursue a relationship/idealize something.',[C('romance.s1','情感','Their summer romance ended amicably when they returned to different cities.','他们的夏日恋情在两人回到不同城市后友好地结束了。','a romance with/between + people','名词：恋爱中的两个人之间的关系。','couple has love affair.','情感'),C('romance.s2','文学','The novel blends romance and adventure against a dramatic mountain setting.','这部小说以壮丽的山景为背景，把爱情与冒险故事结合在一起。','a romance novel/story; romance of + adventure','名词：爱情或冒险故事；也指浪漫、激动人心的氛围。','novel tells love and adventure.','文学'),C('romance.s3','书面','The travel writer romanticized the remote village as a place untouched by modern life.','这位旅行作家把偏远村庄描绘成未受现代生活影响的地方，带有理想化色彩。','romance someone; romanticize/romance an idea','动词：与某人谈恋爱，或以理想化方式谈论某事。','writer idealizes village.','书面')],M('The novel was a romance even though it contained no love, adventure, or idealized setting.','The novel was a romance because it told a love story set in an idealized landscape.','完全没有恋爱、冒险或浪漫化内容与此类故事相反。','meaning'),[Q(1,'A summer romance is…','a love relationship','a list of names','a road surface','Sense 1 means a love affair.','meaning'),Q(2,'A romance novel usually centers on…','love or adventure with an idealized feeling','a technical manual for machines','a robbery investigation only','Sense 2 is a literary story or mood.','context'),Q(3,'To romance an idea is to…','describe it in an idealized way','prove it false with measurements','roll it into a ball','Sense 3 can mean speak of something in an idealized manner.','meaning'),Q(1,'Which phrase is natural?','a romance between two travelers','a romance to two travelers with','romance the travelers as nouning','Between can identify the people in a romantic relationship.','grammar')]);
P('romancer','From romance + -er; romance traces to Old French romanz, a vernacular tale. A romancer writes tales of love or adventure, or invents fanciful stories and embellishes the truth.',C('romancer.s1','文学','The romancer filled his adventure novel with daring voyages and impossible discoveries.','这位传奇作家在冒险小说中写满了大胆航行和不可思议的发现。','a romancer of + tales; a romance writer','名词：爱情或冒险故事的作者，也可指爱编故事的人。','author invents tales.','文学'),M('The romancer refused to invent any stories and reported only bare, verified facts without embellishment.','The romancer embellished the account with imaginative adventures.','拒绝编写、毫不修饰只报事实，与爱编故事相反。','meaning'),[Q(1,'A romancer writes…','tales of love or adventure','road engineering manuals only','a list of residents','A romancer is a writer of romantic or legendary tales.','meaning'),Q(1,'A romancer who embellishes the truth may…','invent fanciful details','remove every imaginative detail','repair a riverbed','The source also uses romancer for someone who makes up stories.','context'),Q(1,'Which phrase is natural?','a romancer of heroic adventures','a romancered adventurely','a romance writer who never writes stories','A romancer can be described as a writer of adventures.','grammar'),Q(1,'Romancer is formed from romance plus…','-er','-ful','-ity','The suffix -er names someone who writes or tells romances.','word-formation')]);
P('romantic','From romance + -ic, with romance from Old French romanz; romantic means connected with love, appealing to emotion or an idealized past, or an impractical idealist.',[C('romantic.s1','情感','He planned a romantic dinner by the lake for their anniversary.','他为纪念日安排了一场湖畔浪漫晚餐。','a romantic evening/gesture/relationship','形容词：与爱情有关或能唤起浪漫情感的。','dinner shows affection.','情感'),C('romantic.s2','性格','Her romantic plan ignored the budget and the rainy forecast.','她不切实际的计划忽视了预算和下雨预报。','a romantic idealist/notion','形容词/名词：受理想而非现实支配；也指持这种观念的人。','plan overlooks practical facts.','性格')],M('His romantic gesture was purely practical and had no connection to affection, feeling, or ideals.','His romantic gesture showed affection and was planned especially for their anniversary.','完全没有感情或理想色彩的实用举动不符合此义。','meaning'),[Q(1,'A romantic dinner is…','planned to express love or affection','a strict financial audit','a noisy road roller','Sense 1 concerns love and emotion.','meaning'),Q(2,'A romantic plan that ignores cost and weather may be…','guided by ideals rather than practical facts','carefully realistic in every detail','a technical requirement','Sense 2 is idealistic and impractical.','context'),Q(1,'Which phrase is natural?','a romantic gesture','a romance gesturely','a romantic of gesture at','Romantic is an adjective modifying gesture.','grammar'),Q(1,'Which sentence uses romantic to mean impractical idealism?','He was romantic about the project and ignored the costs.','They shared a romantic anniversary dinner.','The romance novel was popular.','Ignoring practical costs points to the idealistic sense.','meaning')]);
P('romantically','From romantic + -ly; romantic is from romance, via Old French romanz. Romantically means in a way related to love or with idealized, unrealistic feeling.',C('romantically.s1','情感','The couple romantically described the old bridge as the place where they first met.','这对恋人带着浪漫情愫，把那座旧桥说成他们初次相遇的地方。','romantically involved; romantically describe/idealize','副词：以表现爱情的方式，或带着理想化感情。','couple connects bridge to love.','情感'),M('They spoke romantically about the bridge while expressing no affection, idealism, or emotional connection to it.','They spoke romantically about the bridge as a cherished symbol of their first meeting.','完全没有感情或理想化意味不符合romantically。','meaning'),[Q(1,'They described the bridge romantically because…','it held a special place in their love story','they measured its engineering strength only','they were discussing a roadbed','Romantically can mean with loving or idealized feeling.','meaning'),Q(1,'Which sentence is grammatical?','They were romantically involved for years.','They were romantic involvedly for years.','Romantically, their relationship romantic.','Romantically is the adverb modifying involved.','grammar'),Q(1,'A writer idealizes a simple village as magical and perfect. The writer describes it…','romantically','rigidly','robotically','The description is idealized rather than realistic.','context'),Q(1,'Romantically is formed from…','romantic + -ly','romance + -ness','romancer + -ful','The adverb suffix -ly attaches to romantic.','word-formation')]);
P('romanticism','From romantic + -ism; romantic is from romance. Romanticism is the late-18th- and 19th-century movement emphasizing emotion, nature, and imagination, or a romantic outlook.',C('romanticism.s1','文艺','The museum’s Romanticism exhibit features landscapes that celebrate nature and individual feeling.','博物馆的浪漫主义展览展出了赞美自然与个人情感的风景画。','Romanticism in art/literature; the Romanticism movement','名词：十八世纪末至十九世纪强调情感、自然和想象力的艺术文学运动。','exhibit shows movement themes.','文艺'),M('The lecture defined Romanticism as a movement that rejected emotion, nature, and imagination in favor of strict calculation.','The lecture described Romanticism as a movement that valued emotion, nature, and imagination.','拒绝情感、自然与想象和该运动的核心特征相反。','meaning'),[Q(1,'Romanticism was an artistic movement emphasizing…','emotion, nature, and imagination','robotic efficiency and calculation only','road construction','The movement valued feeling and imagination.','meaning'),Q(1,'Which phrase is natural?','Romanticism in nineteenth-century poetry','Romanticistly in nineteenth-century poetry','romanticismed poetry at','Romanticism names a movement or outlook.','grammar'),Q(1,'A painter values dramatic landscapes and individual emotion. Their work may reflect…','Romanticism','rococo only','rivalry','Those themes are characteristic of the Romantic movement.','context'),Q(1,'The suffix -ism in Romanticism often names…','a movement or system of ideas','a person who performs an action','a past-tense verb','Romanticism refers to an artistic and intellectual movement.','word-formation')]);
P('romanticize','From romantic + -ize; romantic is from romance. Romanticize means describe or think about something as more attractive, noble, or pleasant than it really is.',C('romanticize.s1','态度','The memoir romanticizes farm life and leaves out the long hours and isolation.','这本回忆录把农场生活理想化，略去了漫长工时和孤独感。','romanticize the past/life/person','动词：把现实描写或想象得比实际更美好。','account omits hardship.','态度'),M('The memoir romanticized farm life by emphasizing every hardship accurately and refusing to idealize it.','The memoir romanticized farm life by presenting it as idyllic and omitting its hardships.','准确呈现困苦、不加理想化与romanticize相反。','meaning'),[Q(1,'To romanticize farm life is to…','make it seem more attractive than it really is','list every hardship without idealization','turn it into a rodeo','Romanticize means idealize or make something seem better.','meaning'),Q(1,'Which phrase is natural?','romanticize the past','romanticize to the past of','romantically pastize the','Romanticize takes the thing idealized as its direct object.','grammar'),Q(1,'A writer describes a difficult era as perfect and carefree. The writer…','romanticizes the past','reports it without bias','reschedules the era','The portrayal makes reality seem more pleasant than it was.','context'),Q(1,'The suffix -ize in romanticize means…','make or treat as','a person who writes','without','The verb means make something seem romantic or idealized.','word-formation')]);
P('roof','From Old English hrōf “roof, ceiling,” of Germanic origin; roof is the covering on a building or vehicle, or the top/upper inside surface of something.',[C('roof.s1','建筑','The roof kept the rain out while the crew repaired the damaged windows.','工人维修受损窗户时，屋顶挡住了雨水。','a roof over + building; repair/replace the roof','名词：覆盖建筑物顶部的结构。','cover protects house.','建筑'),C('roof.s2','通用','The driver secured the luggage to the roof of the car.','司机把行李固定在汽车车顶上。','roof of a vehicle; roof of the mouth','名词：车辆顶部，也指口腔上部。','luggage sits on car top.','通用')],M('The house had a roof over its rooms, but rain fell directly inside because the covering was missing.','The house’s roof covered its rooms and kept rain out.','没有覆盖结构就不能防雨。','meaning'),[Q(1,'A roof on a house is…','the structure covering its top','the ground under its floor','a road for cars','Sense 1 is the building covering.','meaning'),Q(2,'The roof of a car is…','its upper outside surface','the car’s wheel rim','the road beneath the car','Sense 2 includes the top of a vehicle.','context'),Q(1,'Which phrase is natural?','repair the roof of the house','repair the roof under the house’s foundation','roofing the house inside out with no top','A roof covers the top of a building.','grammar'),Q(2,'The roof of the mouth refers to…','the upper inside surface of the mouth','the car’s trunk','the top of a riverbank','Roof can also mean the upper surface inside the mouth.','meaning')]);
P('rooftop','From roof + top; roof is from Old English hrōf. A rooftop is the outside top surface of a building or the area on top of it.',C('rooftop.s1','建筑','Solar panels covered most of the rooftop above the apartment building.','公寓楼上方的大部分屋顶都安装了太阳能电池板。','on/above the rooftop; rooftop garden','名词：建筑物屋顶外侧的顶部表面或其上方区域。','panels lie on building top.','建筑'),M('The rooftop was below the basement floor, beneath the ground rather than on top of the building.','The rooftop was above the top floor, on the outside top of the building.','roof top位于建筑物最上方，不在地下室下方。','meaning'),[Q(1,'A rooftop is…','the outside top of a building','the lowest basement room','the riverbed beneath a bridge','Rooftop means the roof’s top surface or area.','meaning'),Q(1,'Which phrase is natural?','a rooftop garden','a rooftop garden beneath the foundation','a roofly toping garden','A garden may be located on a rooftop.','grammar'),Q(1,'Workers install solar panels above the top floor. They work on the…','rooftop','roadbed','riverbank','The panels are installed on the building’s top.','context'),Q(1,'Rooftop combines roof and…','top','rival','roll','The compound names the top of a roof.','word-formation')]);
})();
